class Mapping(Collection):
    """A Mapping is a generic container for associating key/value
    pairs.

    This class provides concrete generic implementations of all
    methods except for __getitem__, __iter__, and __len__.
    """

    __slots__ = ()

    # Tell ABCMeta.__new__ that this class should have TPFLAGS_MAPPING set.
    __abc_tpflags__ = 1 << 6 # Py_TPFLAGS_MAPPING

    @abstractmethod
    def __getitem__(self, key):
        raise KeyError

    def get(self, key, default=None):
        'D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.'
        try:
            return self[key]
        except KeyError:
            return default

    def __contains__(self, key):
        try:
            self[key]
        except KeyError:
            return False
        else:
            return True

    def keys(self):
        "D.keys() -> a set-like object providing a view on D's keys"
        return KeysView(self)

    def items(self):
        "D.items() -> a set-like object providing a view on D's items"
        return ItemsView(self)

    def values(self):
        "D.values() -> an object providing a view on D's values"
        return ValuesView(self)

    def __eq__(self, other):
        if not isinstance(other, Mapping):
            return NotImplemented
        return dict(self.items()) == dict(other.items())

    __reversed__ = None

Mapping.register(mappingproxy)
Mapping.register(framelocalsproxy)


class MappingView(Sized):

    __slots__ = '_mapping',

    def __init__(self, mapping):
        self._mapping = mapping

    def __len__(self):
        return len(self._mapping)

    def __repr__(self):
        return '{0.__class__.__name__}({0._mapping!r})'.format(self)

    __class_getitem__ = classmethod(GenericAlias)


class KeysView(MappingView, Set):

    __slots__ = ()

    @classmethod
    def _from_iterable(cls, it):
        return set(it)

    def __contains__(self, key):
        return key in self._mapping

    def __iter__(self):
        yield from self._mapping


KeysView.register(dict_keys)


class ItemsView(MappingView, Set):

    __slots__ = ()

    @classmethod
    def _from_iterable(cls, it):
        return set(it)

    def __contains__(self, item):
        key, value = item
        try:
            v = self._mapping[key]
        except KeyError:
            return False
        else:
            return v is value or v == value

    def __iter__(self):
        for key in self._mapping:
            yield (key, self._mapping[key])


ItemsView.register(dict_items)


class ValuesView(MappingView, Collection):

    __slots__ = ()

    def __contains__(self, value):
        for key in self._mapping:
            v = self._mapping[key]
            if v is value or v == value:
                return True
        return False

    def __iter__(self):
        for key in self._mapping:
            yield self._mapping[key]


ValuesView.register(dict_values)


class MutableMapping(Mapping):
    """A MutableMapping is a generic container for associating
    key/value pairs.

    This class provides concrete generic implementations of all
    methods except for __getitem__, __setitem__, __delitem__,
    __iter__, and __len__.
    """

    __slots__ = ()

    @abstractmethod
    def __setitem__(self, key, value):
        raise KeyError

    @abstractmethod
    def __delitem__(self, key):
        raise KeyError

    __marker = object()

    def pop(self, key, default=__marker):
        '''D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
          If key is not found, d is returned if given, otherwise KeyError is raised.
        '''
        try:
            value = self[key]
        except KeyError:
            if default is self.__marker:
                raise
            return default
        else:
            del self[key]
            return value

    def popitem(self):
        '''D.popitem() -> (k, v), remove and return some (key, value) pair
           as a 2-tuple; but raise KeyError if D is empty.
        '''
        try:
            key = next(iter(self))
        except StopIteration:
            raise KeyError from None
        value = self[key]
        del self[key]
        return key, value

    def clear(self):
        'D.clear() -> None.  Remove all items from D.'
        try:
            while True:
                self.popitem()
        except KeyError:
            pass

    def update(self, other=(), /, **kwds):
        ''' D.update([E, ]**F) -> None.  Update D from mapping/iterable E and F.
            If E present and has a .keys() method, does:     for k in E.keys(): D[k] = E[k]
            If E present and lacks .keys() method, does:     for (k, v) in E: D[k] = v
            In either case, this is followed by: for k, v in F.items(): D[k] = v
        '''
        if isinstance(other, Mapping):
            for key in other:
                self[key] = other[key]
        elif hasattr(other, "keys"):
            for key in other.keys():
                self[key] = other[key]
        else:
            for key, value in other:
                self[key] = value
        for key, value in kwds.items():
            self[key] = value

    def setdefault(self, key, default=None):
        'D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D'
        try:
            return self[key]
        except KeyError:
            self[key] = default
        return default


MutableMapping.register(dict)


### SEQUENCES ###

class Sequence(Reversible, Collection):
    """All the operations on a read-only sequence.

    Concrete subclasses must override __new__ or __init__,
    __getitem__, and __len__.
    """

    __slots__ = ()

    # Tell ABCMeta.__new__ that this class should have TPFLAGS_SEQUENCE set.
    __abc_tpflags__ = 1 << 5 # Py_TPFLAGS_SEQUENCE

    @abstractmethod
    def __getitem__(self, index):
        raise IndexError

    def __iter__(self):
        i = 0
        try:
            while True:
                v = self[i]
                yield v
                i += 1
        except IndexError:
            return

    def __contains__(self, value):
        for v in self:
            if v is value or v == value:
                return True
        return False

    def __reversed__(self):
        for i in reversed(range(len(self))):
            yield self[i]

    def index(self, value, start=0, stop=None):
        '''S.index(value, [start, [stop]]) -> integer -- return first index of value.
           Raises ValueError if the value is not present.

           Supporting start and stop arguments is optional, but
           recommended.
        '''
        if start is not None and start < 0:
            start = max(len(self) + start, 0)
        if stop is not None and stop < 0:
            stop += len(self)

        i = start
        while stop is None or i < stop:
            try:
                v = self[i]
            except IndexError:
                break
            if v is value or v == value:
                return i
            i += 1
        raise ValueError

    def count(self, value):
        'S.count(value) -> integer -- return number of occurrences of value'
        return sum(1 for v in self if v is value or v == value)

Sequence.register(tuple)
Sequence.register(str)
Sequence.register(bytes)
Sequence.register(range)
Sequence.register(memoryview)

class _DeprecateByteStringMeta(ABCMeta):
    def __new__(cls, name, bases, namespace, **kwargs):
        if name != "ByteString":
            import warnings

            warnings._deprecated(
                "collections.abc.ByteString",
                remove=(3, 17),
            )
        return super().__new__(cls, name, bases, namespace, **kwargs)

    def __instancecheck__(cls, instance):
        import warnings

        warnings._deprecated(
            "collections.abc.ByteString",
            remove=(3, 17),
        )
        return super().__instancecheck__(instance)

class ByteString(Sequence, metaclass=_DeprecateByteStringMeta):
    """Deprecated ABC serving as a common supertype of ``bytes`` and ``bytearray``.

    This ABC is scheduled for removal in Python 3.17.
    Use ``isinstance(obj, collections.abc.Buffer)`` to test if ``obj``
    implements the buffer protocol at runtime. For use in type annotations,
    either use ``Buffer`` or a union that explicitly specifies the types your
    code supports (e.g., ``bytes | bytearray | memoryview``).
    """

    __slots__ = ()

ByteString.register(bytes)
ByteString.register(bytearray)


class MutableSequence(Sequence):
    """All the operations on a read-write sequence.

    Concrete subclasses must provide __new__ or __init__,
    __getitem__, __setitem__, __delitem__, __len__, and insert().
    """

    __slots__ = ()

    @abstractmethod
    def __setitem__(self, index, value):
        raise IndexError

    @abstractmethod
    def __delitem__(self, index):
        raise IndexError

    @abstractmethod
    def insert(self, index, value):
        'S.insert(index, value) -- insert value before index'
        raise IndexError

    def append(self, value):
        'S.append(value) -- append value to the end of the sequence'
        self.insert(len(self), value)

    def clear(self):
        'S.clear() -> None -- remove all items from S'
        try:
            while True:
                self.pop()
        except IndexError:
            pass

    def reverse(self):
        'S.reverse() -- reverse *IN PLACE*'
        n = len(self)
        for i in range(n//2):
            self[i], self[n-i-1] = self[n-i-1], self[i]

    def extend(self, values):
        'S.extend(iterable) -- extend sequence by appending elements from the iterable'
        if values is self:
            values = list(values)
        for v in values:
            self.append(v)

    def pop(self, index=-1):
        '''S.pop([index]) -> item -- remove and return item at index (default last).
           Raise IndexError if list is empty or index is out of range.
        '''
        v = self[index]
        del self[index]
        return v

    def remove(self, value):
        '''S.remove(value) -- remove first occurrence of value.
           Raise ValueError if the value is not present.
        '''
        del self[self.index(value)]

    def __iadd__(self, values):
        self.extend(values)
        return self


MutableSequence.register(list)
MutableSequence.register(bytearray)

files._graphics.py:
"""Graphics for sagebrush: composable primitives that keep their data,
rendered to SVG.

This is the engine under both plotting APIs: Sage's (``plot``, ``point``,
``line``, ... in ``sage_all``) and ``matplotlib.pyplot``.  A figure is a list
of panels (axes); a panel is a list of primitives plus options.  The SVG is
plain text, deterministic, and self-describing:

- every panel carries its data ranges and pixel box (``data-*`` attributes),
  so a browser can show coordinates under the mouse;
- the figure has a text description (``role="img"`` and ``aria-label``),
  for screen readers and for agents that cannot see the picture;
- text and axes use ``currentColor``, so a plot follows a page's light or
  dark theme (saved files render it as black).
"""

import math

# ------------------------------------------------------------------ colors

TAB10 = ["#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd",
         "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf"]
_BASE = {"b": "#0000ff", "g": "#008000", "r": "#ff0000", "c": "#00bfbf",
         "m": "#bf00bf", "y": "#bfbf00", "k": "#000000", "w": "#ffffff"}
_TAB = {"tab:" + n: c for n, c in zip(
    ["blue", "orange", "green", "red", "purple", "brown", "pink", "gray", "olive", "cyan"], TAB10)}
_VIRIDIS = ["#440154", "#482878", "#3e4989", "#31688e", "#26828e",
            "#1f9e89", "#35b779", "#6ece58", "#b5de2b", "#fde725"]


def to_color(c, default=None):
    """A CSS color from a name, hex string, matplotlib code or RGB(A) tuple."""
    if c is None or c == "automatic":
        return default
    if isinstance(c, str):
        if c in _BASE:
            return _BASE[c]
        if len(c) == 2 and c[0] == "C" and c[1].isdigit():
            return TAB10[int(c[1])]
        if c in _TAB:
            return _TAB[c]
        try:  # a grayscale level, as in matplotlib: "0.5"
            v = float(c)
            if 0 <= v <= 1:
                g = round(v * 255)
                return "#%02x%02x%02x" % (g, g, g)
        except ValueError:
            pass
        return c
    if isinstance(c, (tuple, list)) and len(c) in (3, 4):
        r, g, b = (max(0, min(255, round(float(v) * 255))) for v in c[:3])
        return "#%02x%02x%02x" % (r, g, b)
    return str(c)


_CMAPS = {
    "viridis": _VIRIDIS,
    "coolwarm": ["#3b4cc0", "#6788ee", "#9abbff", "#c9d7f0", "#edd1c2", "#f7a889", "#e26952", "#b40426"],
    "jet": ["#00007f", "#0000ff", "#007fff", "#00ffff", "#7fff7f", "#ffff00", "#ff7f00", "#ff0000", "#7f0000"],
    "hot": ["#0b0000", "#4c0000", "#8f0000", "#d10000", "#ff1500", "#ff5800", "#ff9b00", "#ffdd00", "#ffff3f", "#ffffff"],
    "rainbow": ["#7f00ff", "#3f61fa", "#00b4eb", "#40ecd3", "#80feb3", "#c0eb8d", "#ffb360", "#ff6130", "#ff0000"],
    "plasma": ["#0d0887", "#46039f", "#7201a8", "#9c179e", "#bd3786", "#d8576b", "#ed7953", "#fb9f3a", "#fdca26", "#f0f921"],
    "Blues": ["#f7fbff", "#deebf7", "#c6dbef", "#9ecae1", "#6baed6", "#4292c6", "#2171b5", "#08519c", "#08306b"],
    "Spectral": ["#9e0142", "#d53e4f", "#f46d43", "#fdae61", "#fee08b", "#ffffbf", "#e6f598", "#abdda4", "#66c2a5", "#3288bd", "#5e4fa2"],
    "RdBu": ["#67001f", "#b2182b", "#d6604d", "#f4a582", "#fddbc7", "#d1e5f0", "#92c5de", "#4393c3", "#2166ac", "#053061"],
}


def colormap(t, name="viridis"):
    """The color at t in [0, 1] of a colormap: viridis, gray, coolwarm, jet,
    hot, rainbow, plasma, Blues, Spectral, RdBu (a "_r" suffix reverses)."""
    t = 0.0 if t != t else max(0.0, min(1.0, t))
    if not isinstance(name, str) and hasattr(name, "_color"):  # a matplotlib.colors colormap
        return name._color(t)
    name = name if isinstance(name, str) else "viridis"
    if name.endswith("_r"):
        name, t = name[:-2], 1 - t
    if name in ("gray", "grey", "Greys_r", "binary_r"):
        g = round(t * 255)
        return "#%02x%02x%02x" % (g, g, g)
    if name in ("Greys", "binary"):
        g = round((1 - t) * 255)
        return "#%02x%02x%02x" % (g, g, g)
    stops = _CMAPS.get(name, _VIRIDIS)
    x = t * (len(stops) - 1)
    i = min(int(x), len(stops) - 2)
    f = x - i
    a, b = stops[i], stops[i + 1]
    mix = [round(int(a[k:k + 2], 16) * (1 - f) + int(b[k:k + 2], 16) * f) for k in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(mix)


DASHES = {"-": None, "solid": None, "--": "6,4", "dashed": "6,4", ":": "1.5,3",
          "dotted": "1.5,3", "-.": "6,3,1.5,3", "dashdot": "6,3,1.5,3", "": None, "None": None}


# ------------------------------------------------------------------ numbers

def _finite(v):
    try:
        v = float(v)
    except (TypeError, ValueError, OverflowError):
        return None
    if v != v or v in (math.inf, -math.inf):
        return None
    return v


def _fmt(v):
    """Coordinates in the SVG: two decimals, no trailing zeros."""
    s = "%.2f" % v
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return "0" if s == "-0" else s


def _esc(s):
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


# ------------------------------------------------------------ math in text

_TEX_SYMBOLS = {
    "alpha": "α", "beta": "β", "gamma": "γ", "delta": "δ", "epsilon": "ϵ", "varepsilon": "ε", "zeta": "ζ", "eta": "η",
    "theta": "θ", "vartheta": "ϑ", "iota": "ι", "kappa": "κ", "lambda": "λ", "mu": "μ", "nu": "ν", "xi": "ξ", "pi": "π",
    "varpi": "ϖ", "rho": "ρ", "varrho": "ϱ", "sigma": "σ", "varsigma": "ς", "tau": "τ", "upsilon": "υ", "phi": "ϕ",
    "varphi": "φ", "chi": "χ", "psi": "ψ", "omega": "ω", "Gamma": "Γ", "Delta": "Δ", "Theta": "Θ", "Lambda": "Λ",
    "Xi": "Ξ", "Pi": "Π", "Sigma": "Σ", "Upsilon": "Υ", "Phi": "Φ", "Psi": "Ψ", "Omega": "Ω",
    "pm": "±", "mp": "∓", "times": "×", "cdot": "·", "div": "÷", "infty": "∞", "partial": "∂", "nabla": "∇",
    "leq": "≤", "le": "≤", "geq": "≥", "ge": "≥", "neq": "≠", "ne": "≠", "approx": "≈", "sim": "∼", "simeq": "≃",
    "equiv": "≡", "propto": "∝", "langle": "⟨", "rangle": "⟩", "prime": "′", "circ": "∘", "degree": "°",
    "to": "→", "rightarrow": "→", "leftarrow": "←", "Rightarrow": "⇒", "in": "∈", "sum": "∑", "prod": "∏", "int": "∫",
    "oint": "∮", "sqrt": "√", "ell": "ℓ", "hbar": "ℏ", "Re": "ℜ", "Im": "ℑ", "ldots": "…", "cdots": "⋯", "dots": "…",
    "%": "%", "$": "$", "{": "{", "}": "}", "_": "_", "#": "#", "&": "&", ",": "\u2009", ";": "\u2005", ":": "\u2005",
    "!": "", " ": " ", "quad": "\u2003", "qquad": "\u2003\u2003", "log": "log", "ln": "ln", "exp": "exp",
    "sin": "sin", "cos": "cos", "tan": "tan", "max": "max", "min": "min", "lim": "lim", "det": "det",
}
_TEX_FUNCS = {"log", "ln", "exp", "sin", "cos", "tan", "max", "min", "lim", "det"}
# (single symbols: one factor, as a letter is)
_TEX_ATOMS = {"alpha", "beta", "gamma", "delta", "epsilon", "varepsilon", "zeta", "eta", "theta", "vartheta", "iota", "kappa",
              "lambda", "mu", "nu", "xi", "pi", "varpi", "rho", "varrho", "sigma", "varsigma", "tau", "upsilon", "phi", "varphi",
              "chi", "psi", "omega", "Gamma", "Delta", "Theta", "Lambda", "Xi", "Pi", "Sigma", "Upsilon", "Phi", "Psi", "Omega",
              "infty", "partial", "nabla", "ell", "hbar", "Re", "Im"}
# (commands that take one argument)
_TEX_ONE_ARG = {"mathrm", "rm", "text", "textrm", "operatorname", "mathsf", "mathbf", "bf", "textbf", "boldsymbol", "mathit",
                "textit", "it", "overline", "bar", "widebar", "hat", "widehat", "tilde", "widetilde", "vec", "dot", "ddot", "sqrt"}
# (what may follow a fraction without grouping it: operators and relations)
_TEX_AFTER_FRAC = set("+-=<>,;)]}|") | {"\\" + n for n in ("leq", "le", "geq", "ge", "neq", "ne", "approx", "sim", "simeq", "equiv",
                                                         "propto", "to", "rightarrow", "in", "pm", "mp", "times", "cdot", "div",
                                                         "right")}
# (spacing: invisible to a fraction's neighbours, which are looked for past it)
_TEX_SPACING = {"\\" + n for n in (",", ";", ":", "!", " ", "quad", "qquad")} | {"~"}


def _tex_simple(ts, single):
    """Whether a part of an inline \\frac reads correctly beside its slash:
    factors only (letters, numbers, symbols, each perhaps with a sub- or
    superscript), and for a denominator just one; anything else (a sum, a
    product of letters in a denominator, a fraction, a function) is put in
    parentheses, so that the drawing is the same expression."""
    sig = [t for t in ts if not t.isspace()]
    atoms, i, digits = 0, 0, False
    while i < len(sig):
        t = sig[i]
        if t in ("^", "_") and atoms:
            i += 1
            if i < len(sig) and sig[i] == "{":
                depth = 0
                while i < len(sig):
                    depth += {"{": 1, "}": -1}.get(sig[i], 0)
                    i += 1
                    if depth == 0:
                        break
            else:
                i += 1
            digits = False
            continue
        if t.isdigit() or (t == "." and digits):
            atoms += not digits
            digits = True
        elif len(t) == 1 and t.isalpha() or (t.startswith("\\") and t[1:] in _TEX_ATOMS):
            atoms += 1
            digits = False
        else:
            return False
        i += 1
    return atoms == 1 if single else atoms >= 1


def _tex_text(tex):
    """The text _tex_svg draws for a TeX string, without its markup (spaces
    plain): what a reader sees.

    EXAMPLES::

        sage: from _graphics import _tex_text  # sagebrush only
        sage: _tex_text(r'\\frac{x+1}{y+1}'), _tex_text(r'\\frac{1}{2}'), _tex_text(r'\\frac{a}{bc}')  # sagebrush only
        ('(x + 1)/(y + 1)', '1/2', 'a/(bc)')
        sage: _tex_text(r'\\frac{1}{\\frac{a}{b}}'), _tex_text(r'\\frac{a}{b}c'), _tex_text(r'2\\frac{1}{3}'), _tex_text(r'-\\frac{a+b}{\\pi} + 1')  # sagebrush only
        ('1/(a/b)', '(a/b)c', '2(1/3)', '-(a + b)/π + 1')
    """
    import re
    s = re.sub(r"<[^>]*>", "", _tex_svg(tex))
    for a, b in (("&lt;", "<"), ("&gt;", ">"), ("&amp;", "&"), ("\u2005", " "), ("\u2004", " "), ("\u200b", ""), ("\u2212", "-")):
        s = s.replace(a, b)
    return s


def _tex_tokens(s):
    out, i = [], 0
    while i < len(s):
        c = s[i]
        if c == "\\":
            j = i + 1
            if j < len(s) and s[j].isalpha():
                while j < len(s) and s[j].isalpha():
                    j += 1
                out.append(s[i:j])
                i = j
            else:
                out.append(s[i:i + 2])
                i += 2
        else:
            out.append(c)
            i += 1
    return out


def _tex_svg(tex):
    """A TeX math string (matplotlib's mathtext subset) as SVG tspans:
    italic letters, symbols, sub- and superscripts, \\overline, \\mathrm,
    \\mathbf, \\frac and \\sqrt (inline)."""
    toks = _tex_tokens(tex)
    pos = [0]

    def group():
        # the next argument: {...} or one token (spaces before it skipped,
        # as TeX does: \\hat x is x with a hat)
        while pos[0] < len(toks) and toks[pos[0]].isspace():
            pos[0] += 1
        if pos[0] >= len(toks):
            return []
        t = toks[pos[0]]
        pos[0] += 1
        if t != "{":
            # (a command with arguments takes them along: x^\\frac12 is x to
            # the 1/2, not x^\\frac then 12)
            n = 2 if t == "\\frac" else 1 if t[1:] in _TEX_ONE_ARG and t.startswith("\\") else 0
            out = [t]
            for _ in range(n):
                out += ["{"] + group() + ["}"]
            return out
        depth, start = 1, pos[0]
        while pos[0] < len(toks) and depth:
            if toks[pos[0]] == "{":
                depth += 1
            elif toks[pos[0]] == "}":
                depth -= 1
            pos[0] += 1
        return toks[start:pos[0] - 1]

    def render(ts, style, nested=True):
        # (a group's contents: {...}, a style, a script, an accent.  There a
        # fraction cannot see its neighbours, so it is always grouped:
        # 2{\\frac{1}{3}} is 2(1/3), {\\frac{a}{b}}^2 is (a/b)^2, astra's
        # CORR-578-1; a fraction's own parts are judged by _tex_simple)
        style = dict(style, nested=nested)
        sub = list(ts)
        save = pos[0]
        nonlocal_toks = toks[:]
        toks[:] = sub
        pos[0] = 0
        out = run(style)
        toks[:] = nonlocal_toks
        pos[0] = save
        return out

    def piece(text, style):
        if not text:
            return ""
        attrs = ""
        if style.get("it"):
            attrs += ' font-style="italic"'
        if style.get("bf"):
            attrs += ' font-weight="bold"'
        if style.get("over"):
            attrs += ' text-decoration="overline"'
        return "<tspan%s>%s</tspan>" % (attrs, _esc(text)) if attrs else _esc(text)

    def run(style):
        out = []
        while pos[0] < len(toks):
            t = toks[pos[0]]
            pos[0] += 1
            if t in ("^", "_"):
                arg = group()
                up = t == "^"
                inner = render(arg, style)
                # (the shift in the script's own size, back in the base size)
                out.append('<tspan font-size="70%%" dy="%s">%s</tspan><tspan dy="%s">\u200b</tspan>' % (
                    "-0.55em" if up else "0.35em", inner, "0.385em" if up else "-0.245em"))
            elif t == "{":
                pos[0] -= 1
                out.append(render(group(), style))
            elif t == "}":
                continue
            elif t == "~":
                out.append("\u00a0")
            elif t.isspace():
                continue
            elif t.startswith("\\"):
                name = t[1:]
                if name in ("mathrm", "rm", "text", "textrm", "operatorname", "mathsf"):
                    out.append(render(group(), dict(style, it=False)))
                elif name in ("mathbf", "bf", "textbf", "boldsymbol"):
                    out.append(render(group(), dict(style, bf=True)))
                elif name in ("mathit", "textit", "it"):
                    out.append(render(group(), dict(style, it=True)))
                elif name in ("overline", "bar", "widebar"):
                    out.append(render(group(), dict(style, over=True)))
                elif name in ("hat", "widehat", "tilde", "widetilde", "vec", "dot", "ddot"):
                    mark = {"hat": "\u0302", "widehat": "\u0302", "tilde": "\u0303", "widetilde": "\u0303",
                            "vec": "\u20d7", "dot": "\u0307", "ddot": "\u0308"}[name]
                    out.append(render(group(), style) + mark)
                elif name == "frac":
                    # inline, as a/b, grouped wherever a slash alone would
                    # read as another expression (astra's CORR-578-1:
                    # \\frac{x+1}{y+1} was drawn x + 1/y + 1)
                    na, nb = group(), group()
                    a, b = render(na, style, False), render(nb, style, False)
                    if not _tex_simple(na, False):
                        a = "(" + a + ")"
                    if not _tex_simple(nb, True):
                        b = "(" + b + ")"
                    f = "%s/%s" % (a, b)
                    # (and the whole fraction grouped when a factor or a
                    # script is next to it: 2\\frac{1}{3} is 2(1/3), not 21/3)
                    # (spacing skipped on both sides: 1/\\,\\frac{a}{b} is
                    # 1/(a/b), astra's CORR-578-1)
                    rest = [t for t in toks[pos[0]:] if not t.isspace() and t not in _TEX_SPACING]
                    import re
                    before = re.sub(r"<[^>]*>", "", "".join(out)).rstrip("\u200b\u2009\u2005\u2003\u00a0 ")
                    if style.get("nested") or (rest and rest[0] not in _TEX_AFTER_FRAC) or (before and (before[-1].isalnum() or before[-1] in ")]/.")):
                        f = "(" + f + ")"
                    out.append(f)
                elif name == "sqrt":
                    out.append("√(" + render(group(), style) + ")")
                elif name in ("left", "right", "big", "Big", "bigg", "Bigg", "displaystyle", "textstyle", "limits"):
                    continue
                elif name in _TEX_FUNCS:
                    out.append(piece(name, dict(style, it=False)))
                elif name in ("leq", "le", "geq", "ge", "neq", "ne", "approx", "sim", "simeq", "equiv", "propto", "to", "rightarrow", "in"):
                    out.append("\u2004%s\u2004" % _TEX_SYMBOLS[name])
                elif name in ("pm", "mp", "times", "cdot", "div"):
                    out.append("\u2005%s\u2005" % _TEX_SYMBOLS[name])
                elif name in _TEX_SYMBOLS:
                    out.append(piece(_TEX_SYMBOLS[name], dict(style, it=style.get("it") and name[:1].islower() and name in (
                        "alpha", "beta", "gamma", "delta", "epsilon", "varepsilon", "zeta", "eta", "theta", "vartheta", "iota",
                        "kappa", "lambda", "mu", "nu", "xi", "pi", "rho", "sigma", "tau", "upsilon", "phi", "varphi", "chi",
                        "psi", "omega"))))
                else:
                    out.append(piece(name, style))
            elif t in "=<>":
                out.append("\u2004%s\u2004" % _esc(t))  # (relations: spaced, as in TeX)
            elif t in "+-" and out and not out[-1].endswith(("(", "[", "\u2004", "\u2005")):
                out.append("\u2005%s\u2005" % ("\u2212" if t == "-" else t))  # (binary operators)
            elif t == "-":
                out.append("\u2212")
            else:
                out.append(piece(t, dict(style, it=style.get("it") and t.isalpha())))
        return "".join(out)

    return run({"it": True})


def _rich(s):
    """Text for SVG, its $...$ parts typeset (as matplotlib does)."""
    s = str(s)
    if "$" not in s:
        return _esc(s)
    parts, out, i = [], [], 0
    # split on unescaped $
    buf, math = "", False
    while i < len(s):
        c = s[i]
        if c == "\\" and i + 1 < len(s) and s[i + 1] == "$":
            buf += "$" if not math else "\\$"
            i += 2
            continue
        if c == "$":
            parts.append((buf, math))
            buf, math = "", not math
        else:
            buf += c
        i += 1
    if math:  # an unbalanced $: plain text
        return _esc(s)
    parts.append((buf, False))
    for text, m in parts:
        out.append(_tex_svg(text) if m else _esc(text))
    return "".join(out)


def _num(v, step=None):
    """A tick label: as short as the tick spacing allows."""
    if v == 0:
        return "0"
    a = abs(v)
    if a >= 1e6 or a < 1e-4:
        s = "%.3g" % v
        m, _, ex = s.partition("e")
        return m + "e" + str(int(ex)) if ex else s
    if step is not None and step > 0:
        d = 0  # as many decimals as the step needs (0.25 -> 2)
        while d < 12 and abs(step * 10 ** d - round(step * 10 ** d)) > 1e-6 * step * 10 ** d:
            d += 1
        s = "%.*f" % (d, v)
    else:
        s = "%.6g" % v
    if "." in s and "e" not in s:
        s = s.rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def nice_ticks(lo, hi, target=6):
    """Round tick positions covering [lo, hi], about `target` of them."""
    if hi <= lo:
        return [lo], 1.0
    raw = (hi - lo) / target
    mag = 10 ** math.floor(math.log10(raw))
    step = mag
    for m in (1, 2, 2.5, 5, 10):
        if m * mag >= raw:
            step = m * mag
            break
    first = math.ceil(lo / step - 1e-9)
    ticks = []
    k = first
    while k * step <= hi + step * 1e-9:
        ticks.append(round(k * step, 12))
        k += 1
    return ticks, step


# ------------------------------------------------------------------ primitives

class Primitive:
    """A drawable with data coordinates and options."""
    kind = "primitive"

    def __init__(self, **options):
        self.options = options

    def bbox(self):  # (xmin, xmax, ymin, ymax) of finite data, or None
        return None

    def legend(self):
        return self.options.get("legend_label") or self.options.get("label")

    def __repr__(self):
        return "%s defined by %d points" % (type(self).__name__, len(getattr(self, "xs", ())))


def _bbox(xs, ys):
    fx = [x for x, y in zip(xs, ys) if x is not None and y is not None]
    fy = [y for x, y in zip(xs, ys) if x is not None and y is not None]
    if not fx:
        return None
    return (min(fx), max(fx), min(fy), max(fy))


def _coords(points):
    xs, ys = [], []
    for p in points:
        if p is None:
            xs.append(None)
            ys.append(None)
            continue
        x, y = p
        xs.append(_finite(x))
        ys.append(_finite(y))
    return xs, ys


class Line(Primitive):
    """A polyline; None entries (or non-finite values) break it into pieces."""
    kind = "line"

    def __init__(self, xs, ys, **options):
        super().__init__(**options)
        self.xs = [_finite(x) for x in xs]
        self.ys = [_finite(y) for y in ys]

    def bbox(self):
        return _bbox(self.xs, self.ys)

    def svg(self, P):
        o = self.options
        parts, pen = [], False
        for x, y in zip(self.xs, self.ys):
            p = P.map(x, y)
            if p is None:
                pen = False
                continue
            parts.append(("L" if pen else "M") + _fmt(p[0]) + " " + _fmt(p[1]))
            pen = True
        color = to_color(o.get("color"), "#1f77b4")
        out = ""
        if parts:
            dash = DASHES.get(o.get("linestyle", "-"), None)
            out = '<path d="%s" fill="none" stroke="%s" stroke-width="%s" stroke-linejoin="round" stroke-linecap="round"%s%s/>' % (
                "".join(parts), _esc(color), _fmt(o.get("thickness", 1.5)),
                ' stroke-dasharray="%s"' % dash if dash else "",
                ' stroke-opacity="%s"' % _fmt(o["alpha"]) if o.get("alpha") is not None else "")
        if o.get("marker"):
            out += _markers(P, self.xs, self.ys, o.get("marker"), o.get("markersize", 3.5), color, o.get("alpha"))
        return out

    def describe(self):
        n = sum(1 for x, y in zip(self.xs, self.ys) if x is not None and y is not None)
        return "line%s through %d points" % (_label(self), n)


class Points(Primitive):
    kind = "points"

    def __init__(self, xs, ys, **options):
        super().__init__(**options)
        self.xs = [_finite(x) for x in xs]
        self.ys = [_finite(y) for y in ys]

    def bbox(self):
        return _bbox(self.xs, self.ys)

    def svg(self, P):
        o = self.options
        return _markers(P, self.xs, self.ys, o.get("marker", "o"), o.get("size", 3.5),
                        o.get("colors") or to_color(o.get("color"), "#1f77b4"), o.get("alpha"),
                        o.get("sizes"), to_color(o.get("edgecolor")))

    def describe(self):
        n = len(self.xs)
        return "%d point%s%s" % (n, "" if n == 1 else "s", _label(self))


def _markers(P, xs, ys, marker, r, color, alpha, sizes=None, edge=None):
    out = []
    many = isinstance(color, list)
    for i, (x, y) in enumerate(zip(xs, ys)):
        p = P.map(x, y)
        if p is None:
            continue
        px, py = p
        rr = sizes[i] if sizes is not None else r
        c = color[i % len(color)] if many else color
        out.append(_marker(marker, px, py, rr, c, edge))
    if not out:
        return ""
    a = ' opacity="%s"' % _fmt(alpha) if alpha is not None else ""
    return "<g%s>%s</g>" % (a, "".join(out))


def _marker(m, x, y, r, color, edge=None):
    c = _esc(color)
    st = ' stroke="%s" stroke-width="0.8"' % _esc(edge) if edge else ""
    X, Y, R = _fmt(x), _fmt(y), _fmt(r)
    if m in ("o", ".", None, True, "circle"):
        if m == ".":
            R = _fmt(max(1.0, r * 0.45))
        return '<circle cx="%s" cy="%s" r="%s" fill="%s"%s/>' % (X, Y, R, c, st)
    if m in ("s", "square"):
        return '<rect x="%s" y="%s" width="%s" height="%s" fill="%s"%s/>' % (
            _fmt(x - r), _fmt(y - r), _fmt(2 * r), _fmt(2 * r), c, st)
    if m in ("_", "|"):
        d = "M%s %sH%s" % (_fmt(x - r), Y, _fmt(x + r)) if m == "_" else "M%s %sV%s" % (X, _fmt(y - r), _fmt(y + r))
        return '<path d="%s" stroke="%s" stroke-width="1.2" fill="none"/>' % (d, c)
    if m in ("+", "x"):
        if m == "+":
            d = "M%s %sH%sM%s %sV%s" % (_fmt(x - r), Y, _fmt(x + r), X, _fmt(y - r), _fmt(y + r))
        else:
            d = "M%s %sL%s %sM%s %sL%s %s" % (_fmt(x - r), _fmt(y - r), _fmt(x + r), _fmt(y + r),
                                            _fmt(x - r), _fmt(y + r), _fmt(x + r), _fmt(y - r))
        return '<path d="%s" stroke="%s" stroke-width="1.5" fill="none"/>' % (d, c)
    shapes = {"^": [(0, -1.2), (1.05, 0.6), (-1.05, 0.6)], "v": [(0, 1.2), (1.05, -0.6), (-1.05, -0.6)],
              "D": [(0, -1.2), (1.2, 0), (0, 1.2), (-1.2, 0)], "d": [(0, -1.2), (0.8, 0), (0, 1.2), (-0.8, 0)],
              "<": [(-1.2, 0), (0.6, -1.05), (0.6, 1.05)], ">": [(1.2, 0), (-0.6, -1.05), (-0.6, 1.05)]}
    if m == "*":
        pts = []
        for k in range(10):
            a = math.pi / 2 + k * math.pi / 5
            rad = 1.4 if k % 2 == 0 else 0.6
            pts.append((rad * math.cos(a), -rad * math.sin(a)))
    else:
        pts = shapes.get(m, shapes["D"])
    d = "M" + "L".join("%s %s" % (_fmt(x + r * a), _fmt(y + r * b)) for a, b in pts) + "Z"
    return '<path d="%s" fill="%s"%s/>' % (d, c, st)


class Polygon(Primitive):
    kind = "polygon"

    def __init__(self, xs, ys, **options):
        super().__init__(**options)
        self.xs = [_finite(x) for x in xs]
        self.ys = [_finite(y) for y in ys]

    def bbox(self):
        return _bbox(self.xs, self.ys)

    def svg(self, P):
        o = self.options
        pts = [P.map(x, y) for x, y in zip(self.xs, self.ys)]
        pts = [p for p in pts if p is not None]
        if len(pts) < 2:
            return ""
        d = "M" + "L".join(_fmt(x) + " " + _fmt(y) for x, y in pts) + "Z"
        fill = to_color(o.get("color"), "#1f77b4") if o.get("fill", True) else "none"
        edge = to_color(o.get("edgecolor"))
        a = o.get("alpha")
        return '<path d="%s" fill="%s"%s%s/>' % (
            d, _esc(fill), ' fill-opacity="%s"' % _fmt(a) if a is not None else "",
            ' stroke="%s" stroke-width="%s"' % (_esc(edge), _fmt(o.get("thickness", 1))) if edge else "")

    def describe(self):
        return "filled region%s" % _label(self)


class Rects(Primitive):
    """Bars: (x, y, width, height) in data coordinates."""
    kind = "bars"

    def __init__(self, rects, **options):
        super().__init__(**options)
        self.rects = [tuple(float(v) for v in r) for r in rects]

    def bbox(self):
        if not self.rects:
            return None
        xs = [r[0] for r in self.rects] + [r[0] + r[2] for r in self.rects]
        ys = [r[1] for r in self.rects] + [r[1] + r[3] for r in self.rects]
        return (min(xs), max(xs), min(ys), max(ys))

    def svg(self, P):
        o = self.options
        colors = o.get("colors")
        fill = to_color(o.get("color"), "#1f77b4")
        edge = to_color(o.get("edgecolor"))
        out = []
        for i, (x, y, w, h) in enumerate(self.rects):
            if P.ylog and y <= 0:  # a bar from 0 on a log axis starts at the bottom
                h, y = y + h - P.ylo, P.ylo
            if P.xlog and x <= 0:
                w, x = x + w - P.xlo, P.xlo
            a, b = P.map(x, y, clamp=True), P.map(x + w, y + h, clamp=True)
            if a is None or b is None:
                continue
            c = colors[i % len(colors)] if colors else fill
            out.append('<rect x="%s" y="%s" width="%s" height="%s" fill="%s"%s/>' % (
                _fmt(min(a[0], b[0])), _fmt(min(a[1], b[1])), _fmt(abs(b[0] - a[0])), _fmt(abs(b[1] - a[1])), _esc(c),
                ' stroke="%s" stroke-width="0.8"' % _esc(edge) if edge else ""))
        a = o.get("alpha")
        return "<g%s>%s</g>" % (' opacity="%s"' % _fmt(a) if a is not None else "", "".join(out))

    def describe(self):
        return "%d bars%s" % (len(self.rects), _label(self))


class Patches(Primitive):
    """Many filled polygons, each with its own color (contour and density
    plots).  Polygons of one color are drawn as one path."""
    kind = "patches"

    def __init__(self, polys, colors, **options):
        super().__init__(**options)
        self.polys = polys      # [[(x, y), ...], ...] in data coordinates
        self.colors = colors    # a CSS color per polygon

    def bbox(self):
        b = self.options.get("bbox")
        if b is not None:
            return b
        pts = [q for poly in self.polys for q in poly]
        if not pts:
            return None
        return (min(q[0] for q in pts), max(q[0] for q in pts), min(q[1] for q in pts), max(q[1] for q in pts))

    def svg(self, P):
        groups = {}
        for poly, c in zip(self.polys, self.colors):
            pts = [P.map(x, y) for x, y in poly]
            if any(p is None for p in pts) or len(pts) < 3:
                continue
            groups.setdefault(c, []).append("M" + "L".join(_fmt(x) + " " + _fmt(y) for x, y in pts) + "Z")
        a = self.options.get("alpha")
        out = []
        for c in sorted(groups):
            out.append('<path d="%s" fill="%s" stroke="%s" stroke-width="0.5" stroke-linejoin="round"/>' % (
                "".join(groups[c]), _esc(c), _esc(c)))
        return "<g%s>%s</g>" % (' opacity="%s"' % _fmt(a) if a is not None else "", "".join(out))

    def describe(self):
        return self.options.get("what") or "%d colored regions" % len(self.polys)


class Segments(Primitive):
    """Many short segments (slope fields), with arrowheads (vector fields)."""
    kind = "segments"

    def __init__(self, segs, **options):
        super().__init__(**options)
        self.segs = segs        # [((x0, y0), (x1, y1)), ...]

    def bbox(self):
        b = self.options.get("bbox")
        if b is not None:
            return b
        pts = [q for s in self.segs for q in s]
        if not pts:
            return None
        return (min(q[0] for q in pts), max(q[0] for q in pts), min(q[1] for q in pts), max(q[1] for q in pts))

    def svg(self, P):
        o = self.options
        color = to_color(o.get("color"), "#1f77b4")
        colors = o.get("colors")
        heads = o.get("heads", False)
        by = {}
        for i, (a, b) in enumerate(self.segs):
            pa, pb = P.map(*a), P.map(*b)
            if pa is None or pb is None:
                continue
            c = colors[i] if colors else color
            d = by.setdefault(c, [[], []])
            d[0].append("M%s %sL%s %s" % (_fmt(pa[0]), _fmt(pa[1]), _fmt(pb[0]), _fmt(pb[1])))
            if heads:
                dx, dy = pb[0] - pa[0], pb[1] - pa[1]
                L = math.hypot(dx, dy)
                if L > 0.5:
                    h = min(6.0, 0.4 * L)
                    ux, uy = dx / L, dy / L
                    bx, by_ = pb[0] - ux * h, pb[1] - uy * h
                    d[1].append("M%s %sL%s %sL%s %sZ" % (_fmt(pb[0]), _fmt(pb[1]), _fmt(bx - uy * h * 0.45), _fmt(by_ + ux * h * 0.45),
                                                       _fmt(bx + uy * h * 0.45), _fmt(by_ - ux * h * 0.45)))
        out = []
        for c in sorted(by):
            lines, hs = by[c]
            out.append('<path d="%s" stroke="%s" stroke-width="%s" stroke-linecap="round" fill="none"/>' % (
                "".join(lines), _esc(c), _fmt(o.get("thickness", 1.2))))
            if hs:
                out.append('<path d="%s" fill="%s"/>' % ("".join(hs), _esc(c)))
        return "<g>%s</g>" % "".join(out)

    def describe(self):
        return self.options.get("what") or "%d segments" % len(self.segs)


class Text(Primitive):
    kind = "text"

    def __init__(self, string, x, y, **options):
        super().__init__(**options)
        self.string, self.x, self.y = str(string), _finite(x), _finite(y)

    def bbox(self):
        if self.x is None or self.y is None or self.options.get("no_bbox"):
            return None
        return (self.x, self.x, self.y, self.y)

    def legend(self):
        return None

    def svg(self, P):
        p = P.map(self.x, self.y, clamp=False)
        if p is None:
            return ""
        o = self.options
        anchor = {"left": "start", "right": "end", "center": "middle"}.get(o.get("horizontal_alignment", "center"), "middle")
        base = {"top": "hanging", "bottom": "auto", "center": "middle", "baseline": "auto"}.get(o.get("vertical_alignment", "center"), "middle")
        color = to_color(o.get("color"))
        rot = o.get("rotation", 0)
        # (background_color: a box behind the text, as wide as its
        # characters at about 0.6 em each, placed by the same alignment and
        # turned by the same rotation, CORR-896-6)
        box = ""
        bg = to_color(o.get("background_color"))
        if bg:
            fs = float(o.get("fontsize", 11))
            w, hh = 0.6 * fs * len(self.string) + 4, fs + 2
            x0 = {"start": p[0] - 2, "end": p[0] - w + 2}.get(anchor, p[0] - w / 2)
            y0 = {"hanging": p[1] - 1, "auto": p[1] - fs * 0.8 - 1}.get(base, p[1] - hh / 2)
            box = '<rect x="%s" y="%s" width="%s" height="%s" fill="%s"%s/>' % (
                _fmt(x0), _fmt(y0), _fmt(w), _fmt(hh), _esc(bg),
                ' transform="rotate(%s %s %s)"' % (_fmt(-float(rot)), _fmt(p[0]), _fmt(p[1])) if rot else "")
        return box + '<text x="%s" y="%s" font-size="%s" text-anchor="%s" dominant-baseline="%s"%s%s>%s</text>' % (
            _fmt(p[0]), _fmt(p[1]), _fmt(o.get("fontsize", 11)), anchor, base,
            ' fill="%s"' % _esc(color) if color else "",
            ' transform="rotate(%s %s %s)"' % (_fmt(-float(rot)), _fmt(p[0]), _fmt(p[1])) if rot else "",
            P.markup.svg(self.string, float(o.get("fontsize", 11))) if getattr(P, "markup", None) else _rich(self.string))

    def describe(self):
        return 'text "%s"' % self.string


class Arrow(Primitive):
    kind = "arrow"

    def __init__(self, tail, head, **options):
        super().__init__(**options)
        self.tail = (_finite(tail[0]), _finite(tail[1]))
        self.head = (_finite(head[0]), _finite(head[1]))

    def bbox(self):
        return _bbox([self.tail[0], self.head[0]], [self.tail[1], self.head[1]])

    def svg(self, P):
        a, b = P.map(*self.tail, clamp=False), P.map(*self.head, clamp=False)
        if a is None or b is None:
            return ""
        o = self.options
        c = _esc(to_color(o.get("color"), "currentColor"))
        w = float(o.get("thickness", 1.5))
        dx, dy = b[0] - a[0], b[1] - a[1]
        L = math.hypot(dx, dy) or 1.0
        ux, uy = dx / L, dy / L
        # (shorten: pixels taken off, half at each end, Sage's arrowshorten;
        # head_shorten: the head stops that many more short, at the edge of
        # a graph's vertex marker)
        half = min(float(o.get("shorten", 0)) / 2, L / 2)
        if half:
            a = (a[0] + ux * half, a[1] + uy * half)
            b = (b[0] - ux * half, b[1] - uy * half)
        cut = min(float(o.get("head_shorten", 0)), max(L - 2 * half, 0))
        if cut:
            b = (b[0] - ux * cut, b[1] - uy * cut)
        hl, hw = 4 + 3 * w, 2 + 1.6 * w
        bx, by = b[0] - ux * hl, b[1] - uy * hl
        head = "M%s %sL%s %sL%s %sZ" % (_fmt(b[0]), _fmt(b[1]), _fmt(bx - uy * hw), _fmt(by + ux * hw), _fmt(bx + uy * hw), _fmt(by - ux * hw))
        dash = DASHES.get(o.get("linestyle", "-"), None)
        return '<path d="M%s %sL%s %s" stroke="%s" stroke-width="%s"%s/><path d="%s" fill="%s"/>' % (
            _fmt(a[0]), _fmt(a[1]), _fmt(bx), _fmt(by), c, _fmt(w),
            ' stroke-dasharray="%s"' % dash if dash else "", head, c)

    def describe(self):
        return "arrow from (%s, %s) to (%s, %s)" % (_num(self.tail[0]), _num(self.tail[1]), _num(self.head[0]), _num(self.head[1]))


class Image(Primitive):
    """A raster picture (a data: URL) over the data box [x0, x1] x [y0, y1]:
    contourf's and imshow's large grids, one <image> rather than a rectangle
    per cell."""
    kind = "image"

    def __init__(self, href, x0, x1, y0, y1, **options):
        super().__init__(**options)
        self.href, self.x0, self.x1, self.y0, self.y1 = href, float(x0), float(x1), float(y0), float(y1)

    def bbox(self):
        return (min(self.x0, self.x1), max(self.x0, self.x1), min(self.y0, self.y1), max(self.y0, self.y1))

    def legend(self):
        return None

    def svg(self, P):
        a, b = P.map(self.x0, self.y1, clamp=False), P.map(self.x1, self.y0, clamp=False)
        if a is None or b is None:
            return ""
        x, y = min(a[0], b[0]), min(a[1], b[1])
        w, h = abs(b[0] - a[0]), abs(b[1] - a[1])
        # (options first_row_y and first_col_x: the data coordinates of the
        # picture's first row and column; otherwise its top row is at the top)
        sx = sy = 1
        o = self.options
        if o.get("first_row_y") is not None:
            other = self.y0 if float(o["first_row_y"]) == self.y1 else self.y1
            p, q = P.map(self.x0, float(o["first_row_y"]), clamp=False), P.map(self.x0, other, clamp=False)
            if p is not None and q is not None and p[1] > q[1]:
                sy = -1
        if o.get("first_col_x") is not None:
            other = self.x1 if float(o["first_col_x"]) == self.x0 else self.x0
            p, q = P.map(float(o["first_col_x"]), self.y0, clamp=False), P.map(other, self.y0, clamp=False)
            if p is not None and q is not None and p[0] > q[0]:
                sx = -1
        flip = ""
        if sx != 1 or sy != 1:
            flip = ' transform="matrix(%d 0 0 %d %s %s)"' % (sx, sy, _fmt(2 * x + w if sx < 0 else 0), _fmt(2 * y + h if sy < 0 else 0))
        return '<image href="%s" x="%s" y="%s" width="%s" height="%s" preserveAspectRatio="none"%s%s/>' % (
            _esc(self.href), _fmt(x), _fmt(y), _fmt(w), _fmt(h),
            ' style="image-rendering:pixelated"' if o.get("pixelated") else "", flip)

    def describe(self):
        return self.options.get("what") or "image"


class AxLine(Primitive):
    """A horizontal or vertical line across the panel (axhline, axvline), or
    across the part `span` of it (fractions of the panel's width or height,
    from its left or bottom: matplotlib's xmin and xmax, or ymin and ymax)."""
    kind = "axline"

    def __init__(self, value, vertical, span=(0.0, 1.0), **options):
        super().__init__(**options)
        self.value, self.vertical = float(value), vertical
        self.span = (float(span[0]), float(span[1]))

    def bbox(self):
        # (its value is in the data limits along its own axis only, as
        # matplotlib's: the other axis is the panel's)
        v = self.value
        if not math.isfinite(v):
            return None
        return (v, v, None, None) if self.vertical else (None, None, v, v)

    def svg(self, P):
        o = self.options
        a, b = self.span
        if self.vertical:
            p = P.map(self.value, P.ylo, clamp=False)
            if p is None:
                return ""
            d = "M%s %sV%s" % (_fmt(p[0]), _fmt(P.top + P.h * (1 - a)), _fmt(P.top + P.h * (1 - b)))
        else:
            p = P.map(P.xlo, self.value, clamp=False)
            if p is None:
                return ""
            d = "M%s %sH%s" % (_fmt(P.left + P.w * a), _fmt(p[1]), _fmt(P.left + P.w * b))
        dash = DASHES.get(o.get("linestyle", "-"))
        return '<path d="%s" stroke="%s" stroke-width="%s"%s%s/>' % (
            d, _esc(to_color(o.get("color"), "currentColor")), _fmt(o.get("thickness", 1)),
            ' stroke-dasharray="%s"' % dash if dash else "",
            ' stroke-opacity="%s"' % _fmt(o["alpha"]) if o.get("alpha") is not None else "")

    def describe(self):
        return "%s line at %s = %s" % ("vertical" if self.vertical else "horizontal", "x" if self.vertical else "y", _num(self.value))


def _label(p):
    s = p.legend()
    return ' "%s"' % s if s else ""


# ------------------------------------------------------------------ a panel

class _Placed:
    """Data -> pixel mapping of a laid-out panel."""

    def __init__(self, left, top, w, h, xlo, xhi, ylo, yhi, xlog, ylog):
        self.left, self.top, self.w, self.h = left, top, w, h
        self.xlo, self.xhi, self.ylo, self.yhi = xlo, xhi, ylo, yhi
        self.xlog, self.ylog = xlog, ylog
        self._x0, self._x1 = self._t(xlo, xlog), self._t(xhi, xlog)
        self._y0, self._y1 = self._t(ylo, ylog), self._t(yhi, ylog)

    @staticmethod
    def _t(v, log):
        if not log:
            return v
        return math.log10(v) if v is not None and v > 0 else None

    def map(self, x, y, clamp=True):
        if x is None or y is None:
            return None
        tx, ty = self._t(x, self.xlog), self._t(y, self.ylog)
        if tx is None or ty is None:
            return None
        px = self.left + (tx - self._x0) / (self._x1 - self._x0) * self.w
        py = self.top + self.h - (ty - self._y0) / (self._y1 - self._y0) * self.h
        if clamp:  # keep huge values (tan near a pole) from overflowing the SVG
            px = max(-1e5, min(1e5, px))
            py = max(-1e5, min(1e5, py))
        return px, py


def _range(lo, hi, log):
    """the axis's range: a degenerate one widened (hi < lo stays: an inverted axis, as matplotlib's)"""
    if lo is None:
        return (1.0, 10.0) if log else (-1.0, 1.0)
    if hi == lo or (not log and abs(hi - lo) < 1e-12 * max(1.0, abs(lo))):
        d = abs(lo) * 0.1 if lo else 1.0
        return (lo / 2, lo * 2) if log and lo > 0 else (lo - d, hi + d)
    return lo, hi


def _mpl_nonsingular(vmin, vmax, expander, tiny=1e-15):
    """matplotlib.transforms.nonsingular: a range widened when it is (nearly)
    a point; not finite: -expander to expander (ported from matplotlib,
    NOTICE.md)"""
    if not (math.isfinite(vmin) and math.isfinite(vmax)):
        return -expander, expander
    if vmax < vmin:
        vmin, vmax = vmax, vmin
    maxabs = max(abs(vmin), abs(vmax))
    if maxabs < (1e6 / tiny) * 2.2250738585072014e-308:
        return -expander, expander
    if vmax - vmin <= maxabs * tiny:
        if vmax == 0 and vmin == 0:
            return -expander, expander
        return vmin - expander * abs(vmin), vmax + expander * abs(vmax)
    return vmin, vmax


def _mpl_autoscale(lo, hi, margin):
    """matplotlib's autoscaled view of the data range lo..hi (None: no data):
    the locator's nonsingular, the margins, then its view_limits'"""
    if lo is None:
        return 0.0, 1.0
    lo, hi = _mpl_nonsingular(lo, hi, 0.05)
    d = (hi - lo) * margin
    if not math.isfinite(d):
        d = 0.0
    return _mpl_nonsingular(lo - d, hi + d, 1e-12, 1e-13)


def _mpl_set_lim(lo, hi):
    """matplotlib's Axis._set_lim: a degenerate range widened by 5%, the
    order (an inverted axis) kept"""
    a, b = _mpl_nonsingular(lo, hi, 0.05)
    return (b, a) if lo > hi else (a, b)


# matplotlib's AutoLocator: MaxNLocator's steps 1, 2, 2.5, 5, 10, as its
# "staircase" one decade either side
_MPL_STEPS = (0.1, 0.2, 0.25, 0.5, 1, 2, 2.5, 5, 10, 20)


def mpl_ticks(vmin, vmax, nbins):
    """The ticks matplotlib's AutoLocator puts on an axis from vmin to vmax
    with room for `nbins` intervals (MaxNLocator.tick_values with at least
    two ticks in range; ported from matplotlib.ticker, NOTICE.md), including
    the ticks just outside the range, as its get_xticks() lists them."""
    vmin, vmax = _mpl_nonsingular(min(vmin, vmax), max(vmin, vmax), 1e-13, 1e-14)
    dv = vmax - vmin
    if not math.isfinite(dv):  # (a span past the doubles: matplotlib's numpy.arange fails)
        raise ValueError("arange: cannot compute length")
    meanv = (vmax + vmin) / 2
    offset = 0 if abs(meanv) / dv < 100 else math.copysign(10 ** (math.log10(abs(meanv)) // 1), meanv)
    scale = 10 ** (math.log10(dv / nbins) // 1)
    _vmin, _vmax = vmin - offset, vmax - offset
    steps = [s * scale for s in _MPL_STEPS]
    raw = (_vmax - _vmin) / nbins
    large = [i for i, s in enumerate(steps) if s >= raw]
    istep = large[0] if large else len(steps) - 1
    if offset:  # (more slop when the offset is large for the step)
        tol = lambda step: min(0.4999, max(1e-10, 10 ** (math.log10(abs(offset) / step) - 12)))
    else:
        tol = lambda step: 1e-10
    for step in steps[istep::-1]:
        best_vmin = (_vmin // step) * step
        d, m = divmod(_vmin - best_vmin, step)
        low = d + 1 if abs(m / step - 1) < tol(step) else d
        d, m = divmod(_vmax - best_vmin, step)
        high = d if abs(m / step) < tol(step) else d + 1
        ticks = [k * step + best_vmin for k in _frange(low, high + 1)]
        if sum(1 for t in ticks if _vmin <= t <= _vmax) >= 2:
            break
    return [t + offset for t in ticks]


def _frange(a, b):
    # (numpy.arange(a, b) of floats with step 1)
    out, k = [], 0
    while a + k < b:
        out.append(a + k)
        k += 1
    return out


def _mpl_labels(vals):
    """Tick labels as matplotlib's ScalarFormatter writes them: as many
    decimals as the ticks need, the same for all, and a true minus sign."""
    vals = [float(v) for v in vals]
    d = 0
    for v in vals:
        for k in range(0, 7):
            if abs(round(v, k) - v) <= 1e-9 * max(1.0, abs(v)):
                d = max(d, k)
                break
        else:
            d = 6
    out = []
    for v in vals:
        t = "%.*f" % (d, v)
        if float(t) == 0:
            t = t.lstrip("-")
        out.append(t.replace("-", "\u2212"))
    return out


def _log_ticks(lo, hi):
    a, b = math.floor(math.log10(lo) + 1e-9), math.ceil(math.log10(hi) - 1e-9)
    return [10.0 ** k for k in range(a, b + 1) if lo * (1 - 1e-9) <= 10.0 ** k <= hi * (1 + 1e-9)]


def _pow10_label(v):
    # (as matplotlib: 10 with the exponent raised)
    k = int(round(math.log10(v)))
    return '10<tspan font-size="70%%" dy="-0.55em">%s</tspan><tspan dy="0.385em">\u200b</tspan>' % (("\u2212%d" % -k) if k < 0 else k)


class Panel:
    """One set of axes: primitives plus options.

    Options: title, title_weight, subtitle ((text, weight), a line under the title),
    markup (an object whose svg(text, size) and plain(text) render the text
    given (titles, labels, legends, tick labels, texts) instead of $...$ math),
    xlabel, ylabel, xmin, xmax, ymin, ymax, xscale/yscale
    ('linear' or 'log'), grid, legend (None: when labels exist; False: never),
    legend_loc, aspect_ratio (1 for equal scales), frame (a box with ticks,
    matplotlib style) or Sage's axes crossing at the origin, axes (False:
    none), xticks/yticks (positions), xticklabels/yticklabels, margins.

    Colors (CSS; each absent one is the page's text color, so the plot
    follows a light or dark theme): facecolor (the plot area's background),
    edgecolor and frame_width (the frame), grid_color, grid_dash (an SVG
    dasharray), grid_width, grid_alpha, grid_above (the grid over the
    data), xtick_color/ytick_color (ticks and their labels), label_color
    (axis labels), title_color.
    """

    def __init__(self, primitives=None, **options):
        self.primitives = list(primitives or [])
        self.options = options

    def data_bbox(self):
        """(xmin, xmax, ymin, ymax) of the primitives' data, None where none
        has any (an axhline has a y only), or None"""
        boxes = [b for b in (p.bbox() for p in self.primitives) if b is not None]
        if not boxes:
            return None

        def side(i, f):
            vals = [b[i] for b in boxes if b[i] is not None]
            return f(vals) if vals else None
        return (side(0, min), side(1, max), side(2, min), side(3, max))

    def ranges(self, w, h):
        o = self.options
        xlog, ylog = o.get("xscale") == "log", o.get("yscale") == "log"
        bb = self.data_bbox()
        if xlog or ylog:  # only positive values have a place on a log axis
            xs, ys = [], []
            for p in self.primitives:
                if isinstance(p, Rects):
                    pts = [(x + dx, y + dy) for x, y, w, h in p.rects for dx in (0, w) for dy in (0, h)]
                else:
                    pts = zip(getattr(p, "xs", ()), getattr(p, "ys", ()))
                for x, y in pts:
                    if x is not None and y is not None:
                        if xlog and x <= 0 and not isinstance(p, Rects) or ylog and y <= 0 and not isinstance(p, Rects):
                            continue
                        if not (xlog and x <= 0):
                            xs.append(x)
                        if not (ylog and y <= 0):
                            ys.append(y)
            if xs and ys:
                bb = (min(xs), max(xs), min(ys), max(ys))
        xlo, xhi, ylo, yhi = bb if bb else (None, None, None, None)
        m = o.get("margins", 0.0)
        # (matplotlib's autoscaling of a linear axis: a degenerate range
        # widened by 5%, then the margins; an axis without data is 0 to 1)
        mpl = o.get("autoscale") == "matplotlib"
        mx, my = mpl and not xlog, mpl and not ylog
        if mx:
            xlo, xhi = _mpl_autoscale(xlo, xhi, m)
        if my:
            ylo, yhi = _mpl_autoscale(ylo, yhi, m)
        if m and xlo is not None and not mx:
            if xlog:
                f = (xhi / xlo) ** m
                xlo, xhi = xlo / f, xhi * f
            else:
                d = (xhi - xlo) * m
                xlo, xhi = xlo - d, xhi + d
        if m and ylo is not None and not my:
            if ylog:
                f = (yhi / ylo) ** m
                ylo, yhi = ylo / f, yhi * f
            else:
                d = (yhi - ylo) * m
                ylo, yhi = ylo - d, yhi + d
        # (matplotlib's linear axes keep its limits: not the guard below,
        # which widens tiny spans)
        if not mx:
            xlo, xhi = _range(xlo, xhi, xlog)
        if not my:
            ylo, yhi = _range(ylo, yhi, ylog)
        for k, v in (("xmin", "xlo"), ("xmax", "xhi"), ("ymin", "ylo"), ("ymax", "yhi")):
            if o.get(k) is not None:
                val = float(o[k])
                if v == "xlo":
                    xlo = val
                elif v == "xhi":
                    xhi = val
                elif v == "ylo":
                    ylo = val
                else:
                    yhi = val
        xlo, xhi = _mpl_set_lim(xlo, xhi) if mx else _range(xlo, xhi, xlog)
        ylo, yhi = _mpl_set_lim(ylo, yhi) if my else _range(ylo, yhi, ylog)
        # (matplotlib's invert_xaxis/invert_yaxis of an autoscaled axis)
        if o.get("xinvert"):
            xlo, xhi = xhi, xlo
        if o.get("yinvert"):
            ylo, yhi = yhi, ylo
        ar = o.get("aspect_ratio")
        # (fit_aspect with all four limits set: the box takes the shape, the limits stay, as matplotlib's adjustable='box')
        boxed = o.get("fit_aspect") and None not in (o.get("xmin"), o.get("xmax"), o.get("ymin"), o.get("ymax"))
        if ar not in (None, "automatic", "auto") and not xlog and not ylog and not boxed:
            ar = float(ar)
            # (an inverted axis keeps its direction: the spans' signs)
            gx, gy = (1.0 if xhi > xlo else -1.0), (1.0 if yhi > ylo else -1.0)
            sx, sy = w / abs(xhi - xlo), h / (abs(yhi - ylo) * ar)
            if sx > sy:
                c, half = (xlo + xhi) / 2, w / sy / 2
                xlo, xhi = c - gx * half, c + gx * half
            else:
                c, half = (ylo + yhi) / 2, h / (sx * ar) / 2
                ylo, yhi = c - gy * half, c + gy * half
        return xlo, xhi, ylo, yhi, xlog, ylog

    def ticks(self, lo, hi, log, positions, labels, target, axis="x"):
        mpl = self.options.get("tick_format") == "matplotlib"
        bins = (self.options.get("tick_bins") or {}).get(axis)
        lo, hi = min(lo, hi), max(lo, hi)  # (an inverted axis has the same ticks)
        if positions is not None:
            pos = [float(v) for v in positions]
            if labels is not None:
                mk = self.options.get("markup")
                size = float(self.options.get("tick_size", 10.5))
                labs = [mk.svg(s, size) if mk else _rich(s) for s in labels]
            elif mpl:
                labs = _mpl_labels(pos)
            else:
                step = min((abs(b - a) for a, b in zip(pos, pos[1:]) if b != a), default=None)
                labs = [_num(v, step) for v in pos]
            return [(v, s) for v, s in zip(pos, labs) if lo - 1e-9 * abs(hi - lo) <= v <= hi + 1e-9 * abs(hi - lo)]
        if log:
            t = _log_ticks(lo, hi)
            if len(t) >= 2:
                return [(v, _pow10_label(v)) for v in t]
        if bins and not log:
            # (matplotlib's AutoLocator, the ticks in the view, as its axis draws them)
            tol = (hi - lo) * 1e-10
            ticks = [t for t in mpl_ticks(lo, hi, bins) if lo - tol <= t <= hi + tol]
            return list(zip(ticks, _mpl_labels(ticks))) if mpl else [(v, _num(v)) for v in ticks]
        ticks, step = nice_ticks(lo, hi, target)
        if mpl:
            return list(zip(ticks, _mpl_labels(ticks)))
        return [(v, _num(v, step)) for v in ticks]

    def svg(self, x, y, w, h):
        """SVG for this panel inside the box (x, y, w, h); returns (svg, description)."""
        o = self.options
        frame = o.get("frame", False)
        show_axes = o.get("axes", True)
        title, xlabel, ylabel = o.get("title"), o.get("xlabel"), o.get("ylabel")
        mk = o.get("markup")
        rich = (lambda t, size: mk.svg(t, size)) if mk else (lambda t, size: _rich(t))
        # font sizes (pixels): tick labels, axis labels, title
        ts, ls, tts = float(o.get("tick_size", 10.5)), float(o.get("label_size", 12)), float(o.get("title_size", 14))
        right_y = o.get("yaxis_side") == "right"
        # margins around the plot area, for tick labels, axis labels and title
        sub = o.get("subtitle") if title else None
        sub_h = tts + 4 if sub else 0  # (the subtitle's line, under the title)
        top = 10 + (tts + 8 if title else 0) + sub_h
        bottom = (ts * 1.75 + (ls * 1.3 + 4 if xlabel else 6)) if show_axes else 8
        right = 14
        guess = self.ranges(max(w - 70, 50), max(h - top - bottom, 50))
        yt = self.ticks(guess[2], guess[3], guess[5], o.get("yticks"), o.get("yticklabels"), max(3, int(h / 70)), "y")
        lw = max([len(_strip_tags(s)) for _, s in yt] + [1]) * ts * 0.61 + 10 if yt else 4
        left = (lw + (ls + 6 if ylabel else 0)) if show_axes else 8
        if o.get("exact"):
            # (matplotlib's axes: the box is the plot area; labels and the
            # title go outside it)
            left = top = right = bottom = 0
            top = sub_h  # (except a subtitle's line: the title stays where it was)
        pw, ph = max(20, w - left - right), max(20, h - top - bottom)
        ar = o.get("aspect_ratio")
        if o.get("fit_aspect") and ar not in (None, "automatic", "auto") and None not in (
                o.get("xmin"), o.get("xmax"), o.get("ymin"), o.get("ymax")):
            # keep the ranges and shrink the plot area to their shape instead
            xr, yr = abs(float(o["xmax"]) - float(o["xmin"])), abs(float(o["ymax"]) - float(o["ymin"])) * float(ar)
            if xr > 0 and yr > 0:
                k = min(pw / xr, ph / yr)
                left += (pw - xr * k) / 2
                top += (ph - yr * k) / 2
                pw, ph = xr * k, yr * k
        xlo, xhi, ylo, yhi, xlog, ylog = self.ranges(pw, ph)
        P = _Placed(x + left, y + top, pw, ph, xlo, xhi, ylo, yhi, xlog, ylog)
        P.markup = o.get("markup")
        # Sage's axes carry more ticks than matplotlib's frame
        dx, dy = (85, 55) if frame else (60, 45)
        xt = self.ticks(xlo, xhi, xlog, o.get("xticks"), o.get("xticklabels"), max(3, int(pw / dx)))
        yt = self.ticks(ylo, yhi, ylog, o.get("yticks"), o.get("yticklabels"), max(3, int(ph / dy)), "y")

        out = ['<g class="sb-panel" data-xr="%r %r" data-yr="%r %r" data-box="%s %s %s %s"%s%s>' % (
            xlo, xhi, ylo, yhi, _fmt(P.left), _fmt(P.top), _fmt(pw), _fmt(ph),
            ' data-xlog="1"' if xlog else "", ' data-ylog="1"' if ylog else "")]
        cid = "sbclip%d" % _next_id()
        out.append('<clipPath id="%s"><rect x="%s" y="%s" width="%s" height="%s"/></clipPath>' % (
            cid, _fmt(P.left - 4), _fmt(P.top - 4), _fmt(pw + 8), _fmt(ph + 8)))
        if o.get("facecolor") not in (None, "none"):
            out.append('<rect x="%s" y="%s" width="%s" height="%s" fill="%s" stroke="none"/>' % (
                _fmt(P.left), _fmt(P.top), _fmt(pw), _fmt(ph), _esc(o["facecolor"])))
        grid = ""
        if o.get("grid"):
            g = []
            for v, _ in xt:
                p = P.map(v, ylo, clamp=False)
                if p:
                    g.append("M%s %sV%s" % (_fmt(p[0]), _fmt(P.top), _fmt(P.top + ph)))
            for v, _ in yt:
                p = P.map(xlo, v, clamp=False)
                if p:
                    g.append("M%s %sH%s" % (_fmt(P.left), _fmt(p[1]), _fmt(P.left + pw)))
            if any(o.get(k) is not None for k in ("grid_color", "grid_dash", "grid_width", "grid_alpha")):
                grid = '<path d="%s" fill="none" stroke="%s"%s stroke-width="%s"%s/>' % (
                    "".join(g), _esc(o.get("grid_color") or "currentColor"),
                    ' stroke-opacity="%s"' % _fmt(o["grid_alpha"]) if o.get("grid_alpha") is not None else
                    ("" if o.get("grid_color") else ' stroke-opacity="0.15"'),
                    _fmt(o.get("grid_width", 1)), ' stroke-dasharray="%s"' % _esc(o["grid_dash"]) if o.get("grid_dash") else "")
            else:
                grid = '<path d="%s" stroke="currentColor" stroke-opacity="0.15" stroke-width="1"/>' % "".join(g)
            if not o.get("grid_above"):
                out.append(grid)
        if show_axes:
            out.append(self._axes_svg(P, xt, yt, frame))
        out.append('<g clip-path="url(#%s)">' % cid)
        for p in self.primitives:
            out.append(p.svg(P))
        out.append("</g>")
        if grid and o.get("grid_above"):
            out.append(grid)
        if show_axes and frame and any(isinstance(p, Patches) for p in self.primitives):
            # filled regions reach the frame: draw it again on top
            out.append('<rect x="%s" y="%s" width="%s" height="%s" fill="none" stroke="%s" stroke-width="%s"/>' % (
                _fmt(P.left), _fmt(P.top), _fmt(pw), _fmt(ph), _esc(o.get("edgecolor") or "currentColor"), _fmt(o.get("frame_width", 0.8))))
        if show_axes and (xlabel or ylabel):
            if xlabel:
                has_xt = bool(xt)
                out.append('<text x="%s" y="%s" text-anchor="middle" font-size="%s"%s>%s</text>' % (
                    _fmt(P.left + pw / 2), _fmt(P.top + ph + (ts * 1.75 if has_xt else 4) + ls * 1.0), _fmt(ls), _fill(o.get("label_color")), rich(xlabel, ls)))
            if ylabel:
                lwr = max([len(_strip_tags(s)) for _, s in yt] + [1]) * ts * 0.61 + 10 if yt else 4
                pad = float(o.get("ylabel_pad", 0))
                if right_y:
                    cx = P.left + pw + lwr + ls * 0.55 + pad
                    rot = 90 if o.get("ylabel_rotation") == 90 else -90
                else:
                    cx, rot = P.left - lwr - ls * 0.55 - pad, -90
                cy = P.top + ph / 2
                out.append('<text x="%s" y="%s" text-anchor="middle" dominant-baseline="middle" font-size="%s" transform="rotate(%s %s %s)"%s>%s</text>' % (
                    _fmt(cx), _fmt(cy), _fmt(ls), rot, _fmt(cx), _fmt(cy), _fill(o.get("label_color")), rich(ylabel, ls)))
        if title:
            ty = P.top - max(8, tts * 0.6 + 4)
            out.append('<text x="%s" y="%s" text-anchor="middle" font-size="%s"%s%s>%s</text>' % (
                _fmt(P.left + pw / 2), _fmt(ty - sub_h), _fmt(tts),
                ' font-weight="%s"' % _esc(o.get("title_weight", "600")) if o.get("title_weight", "600") != "normal" else "",
                _fill(o.get("title_color")), rich(title, tts)))
            if sub:
                out.append('<text x="%s" y="%s" text-anchor="middle" font-size="%s"%s>%s</text>' % (
                    _fmt(P.left + pw / 2), _fmt(ty), _fmt(tts), ' font-weight="bold"' if sub[1] == "bold" else "", rich(sub[0], tts)))
        out.append(self._legend_svg(P))
        out.append("</g>")
        return "".join(out), self.describe(xlo, xhi, ylo, yhi, xlog, ylog)

    def _axes_svg(self, P, xt, yt, frame):
        out = []
        tick = []
        ts = float(self.options.get("tick_size", 10.5))
        right_y = self.options.get("yaxis_side") == "right"
        o = self.options
        if frame:
            out.append('<rect x="%s" y="%s" width="%s" height="%s" fill="none" stroke="%s" stroke-width="%s"/>' % (
                _fmt(P.left), _fmt(P.top), _fmt(P.w), _fmt(P.h), _esc(o.get("edgecolor") or "currentColor"), _fmt(o.get("frame_width", 0.8))))
            ax_y, ax_x = P.top + P.h, P.left
            skip_x = skip_y = None
        else:
            # Sage: axes cross at the origin when it is in view, else along an edge
            yv = 0.0 if P.ylo <= 0 <= P.yhi and not P.ylog else (P.ylo if P.ylo > 0 or P.ylog else P.yhi)
            xv = 0.0 if P.xlo <= 0 <= P.xhi and not P.xlog else (P.xlo if P.xlo > 0 or P.xlog else P.xhi)
            ax_y = P.map(P.xlo, yv, clamp=False)[1]
            ax_x = P.map(xv, P.ylo, clamp=False)[0]
            out.append('<path d="M%s %sH%sM%s %sV%s" stroke="currentColor" stroke-width="0.8"/>' % (
                _fmt(P.left), _fmt(ax_y), _fmt(P.left + P.w), _fmt(ax_x), _fmt(P.top), _fmt(P.top + P.h)))
            skip_x = xv if (P.ylo < 0 < P.yhi and xv == 0.0) else None
            skip_y = yv if (P.xlo < 0 < P.xhi and yv == 0.0) else None
        labels, ylabels, ytick = [], [], []
        for v, s in xt:
            p = P.map(v, P.ylo, clamp=False)
            if p is None:
                continue
            tick.append("M%s %sv%s" % (_fmt(p[0]), _fmt(ax_y), "4" if frame else "3"))
            if skip_x is not None and abs(v - skip_x) < 1e-12:
                continue
            ly = (P.top + P.h if frame else min(max(ax_y, P.top), P.top + P.h)) + ts * 1.43
            labels.append('<text x="%s" y="%s" text-anchor="middle">%s</text>' % (_fmt(p[0]), _fmt(ly), s))
        for v, s in yt:
            p = P.map(P.xlo, v, clamp=False)
            if p is None:
                continue
            if right_y:
                ytick.append("M%s %sh4" % (_fmt(P.left + P.w), _fmt(p[1])))
                ylabels.append('<text x="%s" y="%s" text-anchor="start" dominant-baseline="middle">%s</text>' % (_fmt(P.left + P.w + 6), _fmt(p[1]), s))
                continue
            ytick.append("M%s %sh%s" % (_fmt(ax_x), _fmt(p[1]), "-4" if frame else "-3"))
            if skip_y is not None and abs(v - skip_y) < 1e-12:
                continue
            lx = (P.left if frame else min(max(ax_x, P.left), P.left + P.w)) - 6
            ylabels.append('<text x="%s" y="%s" text-anchor="end" dominant-baseline="middle">%s</text>' % (_fmt(lx), _fmt(p[1]), s))
        xc, yc = o.get("xtick_color"), o.get("ytick_color")
        if xc is None and yc is None:
            # (both the page's text color: one path and one group, as always)
            out.append('<path d="%s" stroke="currentColor" stroke-width="0.8"/>' % "".join(tick + ytick))
            out.append('<g font-size="%s">%s</g>' % (_fmt(ts), "".join(labels + ylabels)))
        else:
            for c, tk, lb in ((xc, tick, labels), (yc, ytick, ylabels)):
                out.append('<path d="%s" stroke="%s" stroke-width="0.8"/>' % ("".join(tk), _esc(c or "currentColor")))
                out.append('<g font-size="%s"%s>%s</g>' % (_fmt(ts), _fill(c), "".join(lb)))
        return "".join(out)

    def _legend_svg(self, P):
        o = self.options
        if o.get("legend") is False:
            return ""
        if o.get("legend_entries") is not None:
            # (the entries matplotlib's legend() chose when it was called, of
            # whichever axes and whether drawn or not: a hidden artist keeps
            # its text, without a swatch)
            items = list(o["legend_entries"])
        else:
            items = [(p, p.legend()) for p in self.primitives if p.legend()]
        if not items:
            return ""
        mk = o.get("markup")
        w = max(len(mk.plain(s) if mk else str(s)) for _, s in items) * 6.6 + 40
        h = len(items) * 18 + 8
        loc = o.get("legend_loc") or "upper right"
        if isinstance(loc, int):
            loc = {1: "upper right", 2: "upper left", 3: "lower left", 4: "lower right"}.get(loc, "upper right")
        lx = P.left + 8 if "left" in loc else P.left + P.w - w - 8
        ly = P.top + P.h - h - 8 if "lower" in loc else P.top + 8
        out = ['<g class="sb-legend"><rect x="%s" y="%s" width="%s" height="%s" rx="3" style="fill: var(--sb-legend-bg, #fff)" fill-opacity="0.85" stroke="currentColor" stroke-opacity="0.25"/>' % (
            _fmt(lx), _fmt(ly), _fmt(w), _fmt(h))]
        for i, (p, s) in enumerate(items):
            cy = ly + 13 + i * 18
            c = _esc(to_color(p.options.get("color"), "#1f77b4"))
            if p.options.get("hidden"):
                pass  # (an artist not drawn: its text, no swatch)
            elif p.kind in ("line", "axline"):
                dash = DASHES.get(p.options.get("linestyle", "-"))
                out.append('<path d="M%s %sh22" stroke="%s" stroke-width="%s"%s%s/>' % (
                    _fmt(lx + 7), _fmt(cy), c, _fmt(p.options.get("thickness", 1.5)), ' stroke-dasharray="%s"' % dash if dash else "",
                    ' stroke-opacity="%s"' % _fmt(p.options["alpha"]) if p.options.get("alpha") is not None else ""))
                if p.kind == "line" and p.options.get("marker"):  # (a line with markers: one, in the middle, as matplotlib's)
                    out.append(_marker(p.options["marker"], lx + 18, cy, p.options.get("markersize", 3.5), to_color(p.options.get("color"), "#1f77b4")))
            elif p.kind == "points":
                out.append(_marker(p.options.get("marker", "o"), lx + 18, cy, 3.5, to_color(p.options.get("color"), "#1f77b4")))
            else:
                ec = to_color(p.options.get("legend_edge"))  # (a swatch's outline, if its entry asks for one)
                out.append('<rect x="%s" y="%s" width="22" height="10" fill="%s"%s%s/>' % (
                    _fmt(lx + 7), _fmt(cy - 5), c, ' fill-opacity="%s"' % _fmt(p.options["alpha"]) if p.options.get("alpha") is not None else "",
                    ' stroke="%s" stroke-width="1"' % _esc(ec) if ec else ""))
            out.append('<text x="%s" y="%s" dominant-baseline="middle" font-size="11">%s</text>' % (_fmt(lx + 35), _fmt(cy), mk.svg(s, 11) if mk else _rich(s)))
        out.append("</g>")
        return "".join(out)

    def describe(self, xlo, xhi, ylo, yhi, xlog, ylog):
        o = self.options
        parts = []
        plain = o["markup"].plain if o.get("markup") else (lambda s: s)
        if o.get("title"):
            parts.append('"%s"' % (plain(o["title"]) + ("\n" + plain(o["subtitle"][0]) if o.get("subtitle") else "")))
        shown = []
        for p in self.primitives[:8]:
            d, lab = p.describe(), p.kind == "text" and getattr(p, "string", None) or p.legend()
            shown.append(d.replace('"%s"' % lab, '"%s"' % plain(lab), 1) if lab and o.get("markup") else d)
        if len(self.primitives) > 8:
            shown.append("%d more" % (len(self.primitives) - 8))
        parts.append(", ".join(shown) if shown else "empty")
        xl = (" (%s)" % plain(o["xlabel"])) if o.get("xlabel") else ""
        yl = (" (%s)" % plain(o["ylabel"])) if o.get("ylabel") else ""
        parts.append("x%s from %s to %s%s, y%s from %s to %s%s" % (
            xl, _short(xlo), _short(xhi), " log scale" if xlog else "", yl, _short(ylo), _short(yhi), " log scale" if ylog else ""))
        return "; ".join(parts)


def _fill(c):
    """a text's fill attribute for a color, or none for the page's"""
    return ' fill="%s"' % _esc(c) if c else ""


def _short(v):
    s = "%.4g" % v
    return "0" if s == "-0" else s


_ids = [0]


def _next_id():
    _ids[0] += 1
    return _ids[0]


def _strip_tags(s):
    out, inside = [], False
    for ch in s:
        if ch == "<":
            inside = True
        elif ch == ">":
            inside = False
        elif not inside:
            out.append(ch)
    return "".join(out)


def render_frame(panels, width=640, height=480, title=None, markup=None):
    """The SVG body (without the <svg> element) and description of panels laid
    out as [(panel, (fx, fy, fw, fh)), ...] in fractions of the figure."""
    width, height = float(width), float(height)
    top = 30 if title else 0
    body, descs = [], []
    for panel, (fx, fy, fw, fh) in panels:
        if panel.options.get("exact"):
            s, d = panel.svg(fx * width, top + fy * (height - top), fw * width, fh * (height - top))
        else:
            s, d = panel.svg(fx * width + 4, top + fy * (height - top) + 2, fw * width - 8, fh * (height - top) - 4)
        body.append(s)
        descs.append(d)
    if title:
        body.insert(0, '<text x="%s" y="20" text-anchor="middle" font-size="15" font-weight="600">%s</text>' % (
            _fmt(width / 2), markup.svg(title, 15) if markup else _rich(title)))
    kind = "Plot" if len(panels) == 1 else "Figure with %d plots" % len(panels)
    desc = kind + (' "%s"' % (markup.plain(title) if markup else title) if title else "") + ": " + " | ".join(descs)
    return "".join(body), desc


def _svg_open(width, height, desc, cls="sb-plot", extra=""):
    return ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %s %s" width="%s" height="%s" role="img" aria-label="%s" '
            'font-family="system-ui, -apple-system, Segoe UI, Helvetica, Arial, sans-serif" font-size="11" fill="currentColor" class="%s"%s>'
            '<title>%s</title>') % (_fmt(width), _fmt(height), _fmt(width), _fmt(height), _esc(desc), cls, extra, _esc(desc))


def render_svg(panels, width=640, height=480, title=None, markup=None):
    """SVG for panels laid out as [(panel, (fx, fy, fw, fh)), ...] in fractions of the figure."""
    body, desc = render_frame(panels, width, height, title, markup)
    return _svg_open(float(width), float(height), desc) + body + "</svg>"


def render_animation(frames, width=640, height=480, delay=200, iterations=0):
    """An animated SVG from frames [(body, description), ...] shown `delay`
    milliseconds each.  It plays by itself in a browser (CSS animation, looping;
    `iterations` is a hint for players); a page can instead drive it by
    showing one <g class="sb-frame"> at a time."""
    n = len(frames)
    if n == 0:
        return render_svg([], width, height)
    total = n * delay / 1000.0
    desc = "Animation of %d frames, %s s each; first frame: %s; last frame: %s" % (
        n, _short(delay / 1000.0), frames[0][1], frames[-1][1])
    style = ("<style>.sb-frame{visibility:hidden;animation:sb-frame %ss step-end infinite}"
             "@keyframes sb-frame{0%%{visibility:visible}%s%%{visibility:hidden}}</style>") % (
                 _short(total), _short(100.0 / n))
    out = [_svg_open(float(width), float(height), desc, "sb-plot sb-anim",
                     ' data-frames="%d" data-delay="%d" data-iterations="%d"' % (n, int(delay), int(iterations or 0))), style]
    for k, (body, _) in enumerate(frames):
        out.append('<g class="sb-frame" style="animation-delay:%ss">%s</g>' % (_short(k * delay / 1000.0), body))
    out.append("</svg>")
    return "".join(out)


def describe_svg(svg):
    """The description stored in an SVG made by render_svg."""
    i = svg.find("<title>")
    j = svg.find("</title>")
    if i < 0 or j < 0:
        return ""
    return svg[i + 7:j].replace("&quot;", '"').replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")


# ------------------------------------------------------------------ output

def host_display(obj):
    """Display obj richly if the host can: the browser (pyjs), or under
    CPython a Jupyter kernel (obj has _repr_svg_).  True if displayed."""
    import builtins
    d = getattr(builtins, "__pyjs_display__", None)
    if d is not None:
        return d(obj)
    import sys
    ip = sys.modules.get("IPython")
    shell = ip.get_ipython() if ip is not None and hasattr(ip, "get_ipython") else None
    if shell is not None and getattr(shell, "kernel", None) is not None:
        from IPython.display import display
        display(obj)
        return True
    return False


def show(obj, save_name="plot"):
    """Display obj richly when the host can (the browser, Jupyter); else
    write an SVG file and print its path (the command line)."""
    import builtins
    # (a catalog example, catalog/SCHEMA.md: one line per figure, from the
    # description render_svg stores, the same on every runtime; the runner
    # sets __sagebrush_catalog__ to its count of figures)
    count = getattr(builtins, "__sagebrush_catalog__", None)
    if isinstance(count, list):
        count[0] += 1
        print("[figure %d: %s]" % (count[0], describe_svg(obj._repr_svg_())))
        return None
    if getattr(builtins, "__sagebrush_doctest__", False):
        return None  # doctests show the repr only, as Sage's do
    shown = host_display(obj)
    if shown:
        return None
    svg = obj._repr_svg_()
    try:
        import tempfile, os
        fd, path = tempfile.mkstemp(prefix="sagebrush-" + save_name + "-", suffix=".svg")
        os.close(fd)
        with open(path, "w") as f:
            f.write(svg)
    except OSError:  # e.g. a sandbox that may not write files (display printed the repr)
        print("(%s)" % describe_svg(svg)[:300])
        return None
    print("Saved %s (%s)" % (path, describe_svg(svg)[:300]))
    return None


def save_svg(svg, filename):
    if hasattr(filename, "write"):
        filename.write(svg)
        return
    name = str(filename)
    ext = name.rsplit(".", 1)[-1].lower() if "." in name else "svg"
    if ext != "svg":
        raise ValueError("only SVG files can be written (got .%s); use a .svg file name" % ext)
    with open(name, "w") as f:
        f.write(svg)


def save_figure(svg, filename, dpi=None, transparent=False):
    """Sage's Graphics.save: an SVG file, or a PNG (the SVG drawn by
    Sagebrush's PNG module, lib/_png.py: dpi pixels per inch, 100 SVG units
    to the inch, default 100, on white unless transparent).  The other
    formats Sage writes (.eps, .pdf, .pgf, .ps, .sobj) are NotImplementedError;
    any other extension is Sage's ValueError."""
    name = filename if hasattr(filename, "write") else str(filename)
    ext = name.rsplit(".", 1)[-1].lower() if isinstance(name, str) and "." in name else "svg"
    if ext == "svg":
        return save_svg(svg, filename)
    if ext == "png":
        import re
        import _png
        m = re.match(r'<svg [^>]*?width="([^"]*)" height="([^"]*)"', svg)
        if m is None:
            raise ValueError("save: the picture has no size to draw it at")
        try:
            w, h = float(m.group(1)) / 100, float(m.group(2)) / 100
        except ValueError:
            w = h = float("nan")
        # (_png checks the size and dpi, finite and within its limits, first)
        png = _png.figure_png(svg, w, h, 100 if dpi is None else dpi, None if transparent else "white", [])
        with open(name, "wb") as f:
            f.write(png)
        return
    if ext in ("eps", "pdf", "pgf", "ps", "sobj"):
        raise NotImplementedError("saving a picture as .%s is not implemented in Sagebrush: use .svg or .png" % ext)
    raise ValueError("allowed file extensions for images are '.eps', '.pdf', '.pgf', '.png', '.ps', '.sobj', '.svg'!")


# ------------------------------------------------------------------ sampling

def adaptive_sample(f, a, b, plot_points=200, adaptive_tolerance=0.01, adaptive_recursion=5):
    """Sage's plot sampling: plot_points uniform points, then recursive
    midpoint refinement where the curve bends more than the tolerance (as a
    fraction of the y range).  Failed or non-finite values break the line."""
    def ev(x):
        try:
            y = f(x)
        except (ValueError, ZeroDivisionError, OverflowError, ArithmeticError):
            return None
        if isinstance(y, complex):
            return None if abs(y.imag) > 1e-12 else _finite(y.real)
        return _finite(y)

    a, b = float(a), float(b)
    n = max(2, int(plot_points))
    xs = [a + (b - a) * i / (n - 1) for i in range(n)]
    pts = [(x, ev(x)) for x in xs]
    ys = [y for _, y in pts if y is not None]
    if not ys:
        return [x for x, _ in pts], [None] * len(pts)
    tol = (max(ys) - min(ys)) * adaptive_tolerance

    def refine(p, q, level):
        if level >= adaptive_recursion or p[1] is None or q[1] is None:
            return []
        x = (p[0] + q[0]) / 2
        y = ev(x)
        if y is None:
            return [(x, None)]  # undefined here (a pole): break the line
        if abs((p[1] + q[1]) / 2 - y) > tol:
            m = (x, y)
            return refine(p, m, level + 1) + [m] + refine(m, q, level + 1)
        return []

    out = [pts[0]]
    for i in range(len(pts) - 1):
        out.extend(refine(pts[i], pts[i + 1], 0))
        out.append(pts[i + 1])
    return [p[0] for p in out], [p[1] for p in out]

files._interact.py:
"""Sage's @interact: controls for a function's arguments, re-running it
on every change.

    @interact
    def f(n=slider(1, 20, 1, 5), color=selector(['red', 'blue']), grid=True):
        show(plot(sin(n*x), (x, 0, 2*pi), color=color, gridlines=grid))

Controls are inferred from defaults as in Sage: a bool is a checkbox, (a, b)
or (a, b, step) a slider, a list a selector, a range a slider over its
values, anything else an input box.  A host that can show controls (the
browser notebook) implements __pyjs_host__("interact", spec): it draws them,
and sends each change back through _update().  Without such a host the
function simply runs once with the defaults, as in Sage's text mode.
"""

import builtins
import json

_interacts = {}
_next = [0]


class Control:
    """The base class of interact controls.

    EXAMPLES::

        sage: from _interact import Control  # sagebrush only
        sage: Control(3).spec()  # sagebrush only
        {'kind': 'input', 'value': 3}
    """
    kind = "input"

    def __init__(self, default=None, label=None):
        self.default, self.label = default, label

    def __repr__(self):
        return "%s(%s)" % (type(self).__name__, ", ".join("%s=%r" % kv for kv in sorted(self.spec().items()) if kv[0] != "kind"))

    def spec(self):
        """The control's description sent to the page (kind, value, ...).

        EXAMPLES::

            sage: slider(0, 10).spec()  # sagebrush only
            {'ints': True, 'kind': 'slider', 'max': 10.0, 'min': 0.0, 'step': 1.0, 'value': 0.0}
        """
        return {"kind": self.kind, "value": self.default}

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: slider(0, 10).convert(3)  # sagebrush only
            3
        """
        return v


class slider(Control):
    """slider(vmin, vmax, step_size=None, default=None, label=None) or slider(list_of_values).

    EXAMPLES::

        sage: s = slider(0, 10, 1, 5); s  # sagebrush only
        slider(ints=True, max=10.0, min=0.0, step=1.0, value=5.0)
        sage: s.default  # sagebrush only
        5
        sage: slider([1, 2, 4, 8]).spec()  # sagebrush only
        {'kind': 'slider', 'labels': ['1', '2', '4', '8'], 'max': 3, 'min': 0, 'step': 1, 'value': 0}
    """
    kind = "slider"

    def __init__(self, vmin, vmax=None, step_size=None, default=None, label=None, display_value=True):
        super().__init__(default, label)
        if vmax is None:  # a list of values
            self.values = list(vmin)
            self.default = self.values.index(default) if default in self.values else 0
            return
        self.values = None
        self.vmin, self.vmax = vmin, vmax
        ints = all(isinstance(v, int) for v in (vmin, vmax)) and (step_size is None or isinstance(step_size, int))
        self.step = step_size if step_size is not None else (1 if ints else (float(vmax) - float(vmin)) / 100)
        self.ints = ints
        self.default = vmin if default is None else default

    def spec(self):
        """The control's description for the page.

        EXAMPLES::

            sage: slider(0, 10, 2).spec()  # sagebrush only
            {'ints': True, 'kind': 'slider', 'max': 10.0, 'min': 0.0, 'step': 2.0, 'value': 0.0}
        """
        if self.values is not None:
            return {"kind": "slider", "min": 0, "max": len(self.values) - 1, "step": 1, "value": self.default,
                    "labels": [_label(v) for v in self.values]}
        return {"kind": "slider", "min": float(self.vmin), "max": float(self.vmax), "step": float(self.step),
                "value": float(self.default), "ints": self.ints}

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: slider(0, 10, 2).convert(4)  # sagebrush only
            4
        """
        if self.values is not None:
            return self.values[int(v)]
        if self.ints:
            return int(round(float(v)))
        return float(v)


class range_slider(slider):
    """range_slider(vmin, vmax, step_size, default=(a, b)): two values.

    EXAMPLES::

        sage: range_slider(0, 10, 1, (2, 5))  # sagebrush only
        range_slider(ints=True, max=10.0, min=0.0, step=1.0, value=[2.0, 5.0])
    """
    kind = "range"

    def __init__(self, vmin, vmax, step_size=None, default=None, label=None):
        super().__init__(vmin, vmax, step_size, None, label)
        self.default = tuple(default) if default is not None else (vmin, vmax)

    def spec(self):
        """The control's description for the page.

        EXAMPLES::

            sage: range_slider(0, 10, 1, (2, 5)).spec()  # sagebrush only
            {'ints': True, 'kind': 'range', 'max': 10.0, 'min': 0.0, 'step': 1.0, 'value': [2.0, 5.0]}
        """
        return {"kind": "range", "min": float(self.vmin), "max": float(self.vmax), "step": float(self.step),
                "value": [float(v) for v in self.default], "ints": self.ints}

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: range_slider(0, 10, 1, (2, 5)).convert([2, 6])  # sagebrush only
            (2, 6)
        """
        conv = (lambda t: int(round(float(t)))) if self.ints else float
        return (conv(v[0]), conv(v[1]))


class selector(Control):
    """selector(values, label=None, default=None, buttons=False)

    EXAMPLES::

        sage: selector(['red', 'green', 'blue'])  # sagebrush only
        selector(buttons=False, options=['red', 'green', 'blue'], value=0)
    """
    kind = "selector"

    def __init__(self, values, label=None, default=None, buttons=False, nrows=None, ncols=None, width=None):
        self.values = list(values)
        super().__init__(self.values.index(default) if default in self.values else 0, label)
        self.buttons = buttons

    def spec(self):
        """The control's description for the page.

        EXAMPLES::

            sage: selector(['a', 'b']).spec()  # sagebrush only
            {'buttons': False, 'kind': 'selector', 'options': ['a', 'b'], 'value': 0}
        """
        labels = getattr(self, "spec_labels", None) or [_label(v) for v in self.values]
        return {"kind": "selector", "options": labels, "value": self.default,
                "buttons": bool(self.buttons) if self.buttons is not None else len(self.values) <= 4}

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: selector(['a', 'b']).convert(1)  # sagebrush only
            'b'
        """
        return self.values[int(v)]


class checkbox(Control):
    """A checkbox for a boolean argument.

    EXAMPLES::

        sage: checkbox(True, label='grid')  # sagebrush only
        checkbox(value=True)
    """
    kind = "checkbox"

    def __init__(self, default=True, label=None):
        super().__init__(bool(default), label)

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: checkbox(True).convert(False)  # sagebrush only
            False
        """
        return bool(v)


class input_box(Control):
    """input_box(default, label=None, type=None): the text is converted to
    `type`, or to the default's type (numbers are evaluated as Python).

    EXAMPLES::

        sage: input_box(3, label='n')  # sagebrush only
        input_box(value='3')
    """
    kind = "input"

    def __init__(self, default=None, label=None, type=None, width=None, height=1):
        super().__init__(default, label)
        self.type = type

    def spec(self):
        """The control's description for the page.

        EXAMPLES::

            sage: input_box(3).spec()  # sagebrush only
            {'kind': 'input', 'value': '3'}
        """
        return {"kind": "input", "value": "" if self.default is None else str(self.default)}

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: input_box(3).convert('2 + 3')  # sagebrush only
            5
        """
        if self.type is not None:
            return self.type(v)
        if isinstance(self.default, str):
            return v
        if v.strip() == "":
            return None
        import sys
        main = sys.modules.get("__main__")
        return eval(v, dict(main.__dict__) if main is not None and hasattr(main, "__dict__") else {})


class color_selector(Control):
    """A color chooser.

    EXAMPLES::

        sage: color_selector('red')  # sagebrush only
        color_selector(value='#1f77b4')
    """
    kind = "color"

    def __init__(self, default="#1f77b4", label=None, widget=None, hide_box=False):
        from _graphics import to_color
        c = to_color(default)
        super().__init__(c if c.startswith("#") and len(c) == 7 else "#1f77b4", label)


class text_control(Control):
    """Static text among the controls.

    EXAMPLES::

        sage: text_control('Choose n')  # sagebrush only
        text_control(value='Choose n')
    """
    kind = "text"

    def __init__(self, value=""):
        super().__init__(str(value), None)


class button(Control):
    """A button; its value is the number of clicks (ipywidgets' Button).

    EXAMPLES::

        sage: from _interact import button  # sagebrush only
        sage: button('Go').spec()  # sagebrush only
        {'kind': 'button', 'text': 'Go', 'value': 0}
    """
    kind = "button"

    def __init__(self, text="Button", label=""):
        super().__init__(0, label)
        self.text = text

    def spec(self):
        """The control's description for the page.

        EXAMPLES::

            sage: __import__('_interact').button('Go').spec()['text']  # sagebrush only
            'Go'
        """
        return {"kind": "button", "value": 0, "text": self.text}

    def convert(self, v):
        """The number of clicks.

        EXAMPLES::

            sage: __import__('_interact').button().convert(2)  # sagebrush only
            2
        """
        return int(v)


def _label(v):
    return v if isinstance(v, str) else repr(v)


def _control(name, default, initial=None):
    """Sage's abbreviations; `initial` is the parameter's own default when a
    control was given separately (interact(f, n=(0, 10)) with def f(n=3))."""
    c = _abbreviate(default)
    if initial is not None and isinstance(c, slider) and c.values is None:
        c.default = initial
    elif initial is not None and isinstance(c, selector) and initial in c.values:
        c.default = c.values.index(initial)
    return c


def _abbreviate(default):
    if isinstance(default, (Control, fixed)):
        return default
    if isinstance(default, bool):
        return checkbox(default)
    if isinstance(default, tuple) and len(default) in (2, 3) and all(isinstance(v, (int, float)) for v in default):
        a, b = default[0], default[1]
        step = default[2] if len(default) == 3 else None
        ints = all(isinstance(v, int) for v in default)
        mid = (a + b) // 2 if ints else (a + b) / 2
        if step is not None and not ints:
            mid = a + round((mid - a) / step) * step
        return slider(a, b, step, mid)
    if isinstance(default, range):
        vals = list(default)
        return slider(vals, default=vals[len(vals) // 2] if vals else None)
    if isinstance(default, list):
        return selector(default, buttons=None)  # buttons when there are few options
    return input_box(default)


def _signature_defaults(f):
    code = getattr(f, "__code__", None)
    defaults = getattr(f, "__defaults__", None) or ()
    names = list(code.co_varnames[:code.co_argcount]) if code is not None else []
    out = {}
    for name, d in zip(names[len(names) - len(defaults):], defaults):
        out[name] = d
    kw = getattr(f, "__kwdefaults__", None) or {}
    out.update(kw)
    return names, out


class _Interact:
    def __init__(self, f, controls):
        self.f, self.controls = f, controls

    def run(self, values):
        """Run the function with the given control values.

        EXAMPLES::

            sage: from _interact import _interacts  # sagebrush only
        """
        kwargs = {name: c.convert(values[name]) if name in values else c.convert(c.spec()["value"])
                  for name, c in self.controls.items() if c.kind != "text" or isinstance(c, fixed)}
        try:
            result = self.f(**kwargs)
            if result is not None:  # as ipywidgets' interact: show what it returns
                from _graphics import host_display
                if not host_display(result):
                    print(result)
            import sys
            pyplot = sys.modules.get("matplotlib.pyplot")
            if pyplot is not None and hasattr(pyplot, "_flush_figures"):
                pyplot._flush_figures()
        except Exception as err:
            import traceback
            traceback.print_exception(err)


class fixed:
    """A value passed to the function as is, without a control.

    EXAMPLES::

        sage: from _interact import fixed  # sagebrush only
        sage: fixed(5).spec()  # sagebrush only
        {'kind': 'text', 'value': ''}
    """
    kind = "fixed"

    def __init__(self, value):
        self.value = value

    def spec(self):
        """The control's description for the page.

        EXAMPLES::

            sage: __import__('_interact').fixed(5).spec()  # sagebrush only
            {'kind': 'text', 'value': ''}
        """
        return {"kind": "text", "value": ""}

    def convert(self, v):
        """The argument value for a value from the page.

        EXAMPLES::

            sage: __import__('_interact').fixed(5).convert(0)  # sagebrush only
            5
        """
        return self.value


def interact(f=None, layout=None, _abbrev=None, **controls):
    """Decorator: @interact or @interact(n=(0, 10)) or interact(f, n=(0, 10)).

    EXAMPLES::

        sage: @interact  # sagebrush only (Sage's text mode also lists the widgets)
        ....: def f(n=slider(1, 5, 1, 2), grid=True):
        ....:     print(n, grid)
        2 True
    """
    if f is None:
        return lambda g: interact(g, layout=layout, _abbrev=_abbrev, **controls)
    make = _abbrev or _control
    names, defaults = _signature_defaults(f)
    ctrls = {}
    for name in names:
        if name in controls:
            ctrls[name] = make(name, controls[name], defaults.get(name))
        elif name in defaults:
            ctrls[name] = make(name, defaults[name], None)
    for name, d in list(defaults.items()) + list(controls.items()):
        if name not in ctrls:
            ctrls[name] = make(name, d, None)
    _next[0] += 1
    iid = _next[0]
    it = _Interact(f, ctrls)
    _interacts[iid] = it
    spec = {"id": iid, "name": getattr(f, "__name__", "f"), "controls": []}
    for name, c in ctrls.items():
        if isinstance(c, fixed):
            continue
        s = c.spec()
        s["name"] = name
        s["label"] = c.label if c.label is not None else name
        spec["controls"].append(s)
    # without a host that draws controls (CPython), run once with the
    # defaults, as Sage does on the command line
    host = getattr(builtins, "__pyjs_host__", None)
    if host is not None and host("interact", json.dumps(spec)):
        builtins.__pyjs_host__("target", iid)
        try:
            it.run({})
        finally:
            builtins.__pyjs_host__("target", None)
    else:
        it.run({})
    return f


def _update(iid, values_json):
    """Called by the host when a control changes."""
    it = _interacts.get(iid)
    if it is None:
        print("This interact is gone (the interpreter restarted): run its cell again.")
        return
    builtins.__pyjs_host__("target", iid)
    try:
        it.run(json.loads(values_json))
    finally:
        builtins.__pyjs_host__("target", None)

files._limits.py:
"""The engine's configurable limits (plan-ff-limits r3), one state per session.

A host hands the engine one JSON text of at most MAX_BYTES bytes (the CLI's
--limits FILE or SAGEBRUSH_LIMITS=FILE, the browser worker's init message),
or, in the CPython package, a mapping (sagebrush.set_limits).  This module
is the one validator for all of them, and the one state:

    validate(source, name=None)  pure: a new frozen Limits of every key's
                                 resolved value (defaults filled in), or
                                 ValueError("limits: ..."), the first failure
                                 in the plan's order
    propose(snapshot)            replaces the one pending snapshot; only
                                 before finalize
    finalize()                   locks the pending snapshot (or DEFAULTS) and
                                 returns it; later calls return the same
                                 object, and propose then raises RuntimeError

Importing this module has no side effect and locks nothing.  The finite-field
core (_sage_ffsub, _sage_ff) calls finalize() at its import and reads its
budgets from the snapshot; the engine hosts (CLI, browser worker) finalize at
runtime startup, before the first user statement; the CPython package at the
first layer use.  sys._sagebrush_limits is the finalized snapshot.

Every key defaults to unlimited (William, Oct 24: no default work, time or
input-size limit on a user's own computation; interrupting is the control).
A context that wants limits (grading, an instructor's notebook, shared
compute) sets finite values explicitly, and those refuse exactly as before;
"unlimited" may also be given explicitly.  An unlimited value resolves to
UNLIMITED (float infinity), which the consumers' budgets and bounds compare
and subtract like any number.  Memory guards are not limits of this module
and always apply.

These are fail-closed budgets in the user's own interpreter, not a security
boundary against code running in it: the hard walls are the host's (heap,
CPU, run timeouts), and every finite maximum below keeps the budgets under
them.

    sage: import _limits as L
    sage: s = L.validate('{"ff.work": 100000}')
    sage: s["ff.work"], s["ff.embed_max"] is L.UNLIMITED
    (100000, True)
    sage: L.validate('{"ff.work": "unlimited"}') == L.DEFAULTS
    True
    sage: L.validate('{"ff.wrok": 1}')
    Traceback (most recent call last):
    ...
    ValueError: limits: ff.wrok is not a limit of this engine (its limits: ff.conway_work, ff.embed_max, ff.root_bits, ff.work)
"""

import sys as _sys

# An unlimited limit: no refusal in advance (plan-c0 r2).  Infinity, so that
# a budget's charge (cops > budget) never refuses and stays unlimited, and a
# bound's comparison (q <= EMBED_MAX) always holds.
UNLIMITED = float("inf")
UNLIMITED_TEXT = "unlimited"

# key: (default, min, max).  Every default is unlimited (plan-c0 r2); the
# ranges are those of an explicit finite value, unchanged from
# plan-ff-limits r3 (a policy's opt-in limits refuse exactly as the old
# defaults did): ff.work at most 10^8, measured at most 0.51 s per 10^7 cops
# on the reference VM; the others no larger than the old defaults
# (embed_max past 2^20 changes the discrete-log accounting, which is why a
# finite ff.work caps the effective embed_max at 2^20: _sage_ffsub).
TABLE = {
    "ff.conway_work": (UNLIMITED, 10 ** 6, 653528895),
    "ff.embed_max": (UNLIMITED, 2 ** 8, 2 ** 20),
    "ff.root_bits": (UNLIMITED, 64, 1024),
    "ff.work": (UNLIMITED, 10 ** 5, 10 ** 8),
    # C0's per-area follow-up (engine/classgroup, engine/poly): opt-in
    # limits of the class-group searches, the unconditional certificate and
    # integer-polynomial factorization, sent to the engine only when finite
    # (sagebrush/_engine.py); the finite values are the former defaults
    "nf.certify_index_max": (UNLIMITED, 10 ** 3, 2 ** 62),
    "nf.certify_norm_max": (UNLIMITED, 10 ** 3, 2 ** 62),
    "nf.relation_rounds": (UNLIMITED, 1, 10 ** 4),
    "poly.work": (UNLIMITED, 2 ** 20, 2 ** 40),
}
# the defaults before plan-c0 (a policy's finite values, and the tests')
FINITE = {"ff.conway_work": 653528895, "ff.embed_max": 2 ** 20, "ff.root_bits": 1024, "ff.work": 10 ** 7,
          "nf.certify_index_max": 10 ** 6, "nf.certify_norm_max": 10 ** 6, "nf.relation_rounds": 60, "poly.work": 2 ** 33}
MAX_BYTES = 4096   # the serialized text, in UTF-8 bytes
MAX_ENTRIES = 16
MAX_KEY = 64       # characters of a key (CPython mappings)

LOCKED = "sagebrush limits are read once, at the first use: set them before it"


class Limits(object):
    """A frozen mapping of every limit to its resolved value."""

    __slots__ = ("_items",)

    def __init__(self, items):
        object.__setattr__(self, "_items", tuple(sorted(items.items())))

    def __setattr__(self, name, value):
        raise AttributeError("the limits are read-only")

    def __delattr__(self, name):
        raise AttributeError("the limits are read-only")

    def __getitem__(self, key):
        for k, v in self._items:
            if k == key:
                return v
        raise KeyError(key)

    def get(self, key, default=None):
        try:
            return self[key]
        except KeyError:
            return default

    def __contains__(self, key):
        return any(k == key for k, _ in self._items)

    def __iter__(self):
        return iter([k for k, _ in self._items])

    def __len__(self):
        return len(self._items)

    def keys(self):
        return [k for k, _ in self._items]

    def items(self):
        return list(self._items)

    def __eq__(self, other):
        return isinstance(other, Limits) and self._items == other._items

    def __ne__(self, other):
        return not self == other

    def __hash__(self):
        return hash(self._items)

    def __repr__(self):
        return "Limits({%s})" % ", ".join("%r: %s" % (k, UNLIMITED_TEXT if v == UNLIMITED else "%d" % v) for k, v in self._items)


DEFAULTS = Limits({k: v[0] for k, v in TABLE.items()})


class _Object(list):
    """A JSON object's (key, value) pairs, in order (duplicates kept)."""


def _shown(v):
    """A refused value as the user wrote it, briefly: JSON's spelling for
    JSON's values (true, null, 1.5, "big"), else its kind."""
    if v is True:
        return "true"
    if v is False:
        return "false"
    if v is None:
        return "null"
    if isinstance(v, float):
        if v != v:
            return "NaN"
        if v in (float("inf"), float("-inf")):
            return "Infinity" if v > 0 else "-Infinity"
        return repr(v)
    if isinstance(v, str):
        s = v if len(v) <= 40 else v[:40] + "..."
        return '"%s"' % s.replace("\\", "\\\\").replace('"', '\\"')
    if isinstance(v, (_Object, dict)):
        return "an object"
    if isinstance(v, list):
        return "an array"
    return "a %s" % type(v).__name__


def _key_shown(k):
    """A key in a message: at most MAX_KEY characters, one line."""
    s = k if len(k) <= MAX_KEY else k[:MAX_KEY] + "..."
    return "".join(c if c.isprintable() else repr(c)[1:-1] for c in s)


def _fits64(v):
    return -(1 << 63) <= v < (1 << 63)


def _refuse(msg):
    return ValueError("limits: " + msg)


def _check_entries(pairs):
    """The semantic checks of (key, value) pairs whose keys are strings, in
    sorted key order: unknown key, given twice, not an integer, more than 64
    bits, out of range.  A new Limits, or ValueError."""
    out = dict(DEFAULTS.items())
    seen = set()
    for k, v in sorted(pairs, key=lambda kv: kv[0]):
        if k not in TABLE:
            raise _refuse("%s is not a limit of this engine (its limits: %s)" % (_key_shown(k), ", ".join(sorted(TABLE))))
        if k in seen:
            raise _refuse("%s is given more than once" % k)
        seen.add(k)
        if type(v) is str and v == UNLIMITED_TEXT:
            out[k] = UNLIMITED
            continue
        if not isinstance(v, int) or isinstance(v, bool):
            raise _refuse('%s must be an integer or "%s", not %s' % (k, UNLIMITED_TEXT, _shown(v)))
        lo, hi = TABLE[k][1], TABLE[k][2]
        if not _fits64(v):
            raise _refuse("%s is an integer of more than 64 bits" % k)
        if not lo <= v <= hi:
            raise _refuse("%s = %d is outside the range this engine allows, [%d, %d]" % (k, v, lo, hi))
        out[k] = int(v)
    return Limits(out)


def _from_text(text, name):
    what = name if name is not None else "the limits"
    if len(text.encode("utf-8", "surrogatepass")) > MAX_BYTES:
        raise _refuse("%s %s larger than %d bytes" % (what, "is" if name is not None else "are", MAX_BYTES))
    import json as _json
    try:
        root = _json.loads(text, object_pairs_hook=_Object)
    except ValueError as e:
        raise _refuse("%s %s not JSON: %s" % (what, "is" if name is not None else "are", e))
    except RecursionError:
        raise _refuse("%s %s not JSON: nested too deeply" % (what, "is" if name is not None else "are"))
    if not isinstance(root, _Object):
        kind = {list: "an array", type(None): "null", str: "a string", bool: "a boolean"}.get(type(root), "a number")
        raise _refuse("the limits must be a JSON object, not %s" % kind)
    if len(root) > MAX_ENTRIES:
        raise _refuse("more than %d entries" % MAX_ENTRIES)
    return _check_entries(list(root))


def _from_mapping(m):
    # (the structural preflight, on the caller's own mapping, before any
    # sorting, copying or encoding: astra CORR-FFLIMIT-3; its first failure,
    # in the mapping's own order, is the one reported)
    try:
        from collections.abc import Mapping as _Mapping
    except ImportError:  # pragma: no cover
        _Mapping = dict
    if not isinstance(m, (dict, _Mapping)):
        raise _refuse("the limits must be a mapping, not %s" % _shown(m))
    if len(m) > MAX_ENTRIES:
        raise _refuse("more than %d entries" % MAX_ENTRIES)
    pairs = []
    for k in m:
        if not isinstance(k, str):
            if isinstance(k, (int, float)) and not isinstance(k, bool):
                raise _refuse("the key %r is not a string" % k)
            raise _refuse("a key of type %s is not a string" % type(k).__name__)
        if len(k) > MAX_KEY:
            raise _refuse("a key of more than %d characters" % MAX_KEY)
        v = m[k]
        if isinstance(v, str) and str.__str__(v) == UNLIMITED_TEXT:
            # (a str subclass is read as its str value, never through its
            # own methods)
            pairs.append((str(k), UNLIMITED_TEXT))
        else:
            if not isinstance(v, int) or isinstance(v, bool):
                raise _refuse('%s must be an integer or "%s", not %s' % (_key_shown(k), UNLIMITED_TEXT, _shown(v)))
            if not _fits64(v):
                raise _refuse("%s is an integer of more than 64 bits" % _key_shown(k))
            pairs.append((str(k), int(v)))
        if len(pairs) > MAX_ENTRIES:  # (a mapping whose len() said less)
            raise _refuse("more than %d entries" % MAX_ENTRIES)
    return _check_entries(pairs)


def validate(source, name=None):
    """A new frozen Limits from a JSON text (name: the file it came from, for
    messages) or a mapping, or ValueError.  Touches no state."""
    if isinstance(source, str):
        return _from_text(source, name)
    if isinstance(source, (bytes, bytearray)):
        raise _refuse("the limits must be text, not bytes")
    return _from_mapping(source)


_pending = None
_final = None


def propose(snapshot):
    """Make snapshot (from validate) the pending one; RuntimeError once the
    limits are finalized."""
    global _pending
    if _final is not None:
        raise RuntimeError(LOCKED)
    if not isinstance(snapshot, Limits):
        raise TypeError("propose() takes the Limits validate() returns")
    _pending = snapshot


def finalize():
    """Lock the pending snapshot (DEFAULTS if none) and return it; the same
    object every later time."""
    global _final
    if _final is None:
        _final = _pending if _pending is not None else DEFAULTS
        try:
            _sys._sagebrush_limits = _final
        except Exception:  # pragma: no cover (a sys without attributes)
            pass
    return _final


def finalized():
    """Whether the limits are locked."""
    return _final is not None

files._thread.py:
"""_thread for a single-threaded runtime: locks that never contend."""

error = RuntimeError
TIMEOUT_MAX = 2 ** 31


class LockType:
    def __init__(self):
        self._count = 0

    def acquire(self, blocking=True, timeout=-1):
        self._count += 1
        return True

    acquire_lock = acquire

    def release(self):
        if self._count == 0:
            raise RuntimeError("release unlocked lock")
        self._count -= 1

    release_lock = release

    def locked(self):
        return self._count > 0

    def __enter__(self):
        return self.acquire()

    def __exit__(self, *a):
        self.release()


lock = LockType
RLock = LockType


def allocate_lock():
    return LockType()


def get_ident():
    return 1


get_native_id = get_ident


def start_new_thread(function, args, kwargs={}):
    raise RuntimeError("threads are not supported in pyjs")


def _count():
    return 0


def stack_size(size=0):
