            curr_key = keyfunc(curr_value)
            if not (target_key is curr_key or target_key == curr_key):
                return
            yield curr_value
        exhausted = True

    while not exhausted:
        target_key = curr_key
        curr_group = grouper(target_key)
        yield curr_key, curr_group
        if target_key is curr_key or target_key == curr_key:
